import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, resolve, sep, isAbsolute } from "node:path";
import { homedir } from "node:os";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

const AGENT_DIR = process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent");
const AUTH_PATH = join(AGENT_DIR, "auth.json");
const QUOTA_CACHE_PATH = join(AGENT_DIR, "status-line-quota.json");
const IBM_CREDITS_CACHE_PATH = join(AGENT_DIR, "status-line-ibm-credits.json");
const IBM_TEAM_ID = process.env.IBM_SERVICES_ESSENTIALS_TEAM_ID || "6a8d8b68f91e25193bbd853d";
const IBM_BUDGET_URL = `https://servicesessentials.ibm.com/services/integrations/team/${IBM_TEAM_ID}/budget`;
const IBM_API_KEY_HELPER = join(AGENT_DIR, "bin", "ibm-services-essentials-api-key");
const IBM_DEFAULT_MAX_CREDITS = Number(process.env.IBM_SERVICES_ESSENTIALS_MAX_CREDITS || 500);

type QuotaBucket = {
  label: "5h" | "7d";
  percent?: number;
  resetAt?: number;
  resetAfterSeconds?: number;
  family?: string;
  limitName?: string;
};

type QuotaState = {
  updatedAt: number;
  buckets: Partial<Record<"5h" | "7d", QuotaBucket>>;
  families?: Record<string, Partial<Record<"5h" | "7d", QuotaBucket>>>;
  activeLimit?: string;
  planType?: string;
};

type IbmCreditsState = {
  updatedAt: number;
  teamId?: string;
  spendCredits: number;
  maxCredits: number;
  softCredits?: number;
  resetAt?: number;
  blocked?: boolean;
  source: "budget" | "response-header";
};

let quotaState: QuotaState | undefined = loadQuotaCache();
let ibmCreditsState: IbmCreditsState | undefined = loadIbmCreditsCache();
let requestFooterRender: (() => void) | undefined;
let lastIbmBudgetRefreshAt = 0;
let authCache: { mtimeMs: number; value: Record<string, any> } | undefined;

function loadQuotaCache(): QuotaState | undefined {
  try {
    if (!existsSync(QUOTA_CACHE_PATH)) return undefined;
    const parsed = JSON.parse(readFileSync(QUOTA_CACHE_PATH, "utf8"));
    if (!parsed || typeof parsed !== "object") return undefined;
    if (typeof parsed.updatedAt !== "number") return undefined;
    const state = parsed as QuotaState;
    const fiveHour = state.buckets?.["5h"];
    const sevenDay = state.buckets?.["7d"];
    // Older cache versions could combine a model-specific 5h quota with the
    // account-wide 7d quota. Never present percentages from different families
    // as if they form one limit pair.
    if (fiveHour && sevenDay && (fiveHour.family ?? "") !== (sevenDay.family ?? "")) {
      delete state.buckets["5h"];
    }
    return state;
  } catch {
    return undefined;
  }
}

function saveQuotaCache(state: QuotaState): void {
  try {
    writeFileSync(QUOTA_CACHE_PATH, JSON.stringify(state, null, 2) + "\n", { mode: 0o600 });
  } catch {
    // Best-effort cache only; footer should never fail because of this.
  }
}

function loadIbmCreditsCache(): IbmCreditsState | undefined {
  try {
    if (!existsSync(IBM_CREDITS_CACHE_PATH)) return undefined;
    const state = JSON.parse(readFileSync(IBM_CREDITS_CACHE_PATH, "utf8")) as IbmCreditsState;
    if (!Number.isFinite(state.updatedAt) || !Number.isFinite(state.spendCredits) || !Number.isFinite(state.maxCredits)) return undefined;
    return state;
  } catch {
    return undefined;
  }
}

function saveIbmCreditsCache(state: IbmCreditsState): void {
  try {
    writeFileSync(IBM_CREDITS_CACHE_PATH, JSON.stringify(state, null, 2) + "\n", { mode: 0o600 });
  } catch {
    // Best-effort cache only; footer should never fail because of this.
  }
}

function readIbmApiKey(): string | undefined {
  try {
    const key = execFileSync(IBM_API_KEY_HELPER, {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
      timeout: 10_000,
    }).trim();
    return key || undefined;
  } catch {
    return undefined;
  }
}

function storeIbmCredits(state: IbmCreditsState): void {
  ibmCreditsState = state;
  saveIbmCreditsCache(state);
  requestFooterRender?.();
}

async function queryIbmCredits(signal?: AbortSignal): Promise<boolean> {
  const apiKey = readIbmApiKey();
  if (!apiKey) return false;
  lastIbmBudgetRefreshAt = Date.now();

  const response = await fetch(IBM_BUDGET_URL, {
    headers: { "Accept": "application/json", "Authorization": `Bearer ${apiKey}` },
    signal: signal ?? AbortSignal.timeout(15_000),
  });
  if (!response.ok) return false;

  const payload = await response.json() as Record<string, unknown>;
  const spendCredits = coerceNumber(payload.advantageCredits) ?? coerceNumber(payload.spendUsd);
  const maxCredits = coerceNumber(payload.maxAdvantageCredits) ?? coerceNumber(payload.maxBudgetUsd);
  if (spendCredits === undefined || maxCredits === undefined) return false;

  storeIbmCredits({
    updatedAt: Date.now(),
    teamId: typeof payload.teamId === "string" ? payload.teamId : IBM_TEAM_ID,
    spendCredits,
    maxCredits,
    softCredits: coerceNumber(payload.softAdvantageCredits) ?? coerceNumber(payload.softBudgetUsd),
    resetAt: coerceNumber(payload.budgetResetAtEpochSeconds),
    blocked: typeof payload.blocked === "boolean" ? payload.blocked : undefined,
    source: "budget",
  });
  return true;
}

function captureIbmCredits(headersIn: Record<string, string>): boolean {
  const headers: Record<string, string> = {};
  for (const [key, value] of Object.entries(headersIn)) headers[key.toLowerCase()] = value;
  const spendCredits = coerceNumber(headers["x-litellm-key-spend"]);
  if (spendCredits === undefined) return false;

  storeIbmCredits({
    updatedAt: Date.now(),
    teamId: ibmCreditsState?.teamId ?? IBM_TEAM_ID,
    spendCredits,
    maxCredits: ibmCreditsState?.maxCredits ?? IBM_DEFAULT_MAX_CREDITS,
    softCredits: ibmCreditsState?.softCredits,
    resetAt: ibmCreditsState?.resetAt,
    blocked: ibmCreditsState?.blocked,
    source: ibmCreditsState?.source === "budget" ? "budget" : "response-header",
  });
  return true;
}

function formatCwd(cwd: string): string {
  const home = process.env.HOME || process.env.USERPROFILE;
  if (!home) return cwd;
  const resolvedCwd = resolve(cwd);
  const resolvedHome = resolve(home);
  const rel = relative(resolvedHome, resolvedCwd);
  const inside = rel === "" || (rel !== ".." && !rel.startsWith(`..${sep}`) && !isAbsolute(rel));
  return inside ? (rel === "" ? "~" : `~${sep}${rel}`) : cwd;
}

function formatCredits(value: number): string {
  if (!Number.isFinite(value)) return "?";
  if (Math.abs(value) >= 1_000) return value.toLocaleString(undefined, { maximumFractionDigits: 0 });
  return value.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}

function formatIbmCredits(theme: any): string {
  if (!ibmCreditsState) return `${boldLabel(theme, "credits:")}${theme.fg("warning", "pending")}`;
  const available = Math.max(0, ibmCreditsState.maxCredits - ibmCreditsState.spendCredits);
  const ratio = ibmCreditsState.maxCredits > 0 ? available / ibmCreditsState.maxCredits : 0;
  const color = ibmCreditsState.blocked || ratio <= 0.1 ? "error" : ratio <= 0.2 ? "warning" : "success";
  const approximate = ibmCreditsState.source === "response-header" ? "~" : "";
  const reset = ibmCreditsState.resetAt && ibmCreditsState.resetAt * 1000 > Date.now()
    ? ` ${theme.fg("muted", `(resets ${formatWeekdayHHMM(new Date(ibmCreditsState.resetAt * 1000))})`)}`
    : "";
  return `${boldLabel(theme, "credits:")}${theme.fg(color, `${approximate}${formatCredits(available)}/${formatCredits(ibmCreditsState.maxCredits)}`)}${reset}`;
}

function formatTokens(count: number): string {
  if (!Number.isFinite(count) || count <= 0) return "0";
  if (count < 1_000) return String(Math.round(count));
  if (count < 10_000) return `${(count / 1_000).toFixed(1)}k`;
  if (count < 1_000_000) return `${Math.round(count / 1_000)}k`;
  if (count < 10_000_000) return `${(count / 1_000_000).toFixed(1)}M`;
  return `${Math.round(count / 1_000_000)}M`;
}

function colorPercent(theme: any, value: number | undefined, suffix = "%", unknownLabel = `?${suffix}`): string {
  if (value === undefined || !Number.isFinite(value)) return theme.fg("warning", unknownLabel);
  const text = `${Math.max(0, Math.min(999, value)).toFixed(0)}${suffix}`;
  if (value <= 50) return theme.fg("success", text);
  if (value <= 80) return theme.fg("warning", text);
  return theme.fg("error", text);
}

function formatTimeHHMM(date: Date): string {
  return date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit", hour12: false });
}

function formatWeekdayHHMM(date: Date): string {
  return `${date.toLocaleDateString(undefined, { weekday: "short" })} ${formatTimeHHMM(date)}`;
}

function resetDate(bucket: QuotaBucket, observedAt: number): Date | undefined {
  if (bucket.resetAt && Number.isFinite(bucket.resetAt)) return new Date(bucket.resetAt * 1000);
  if (bucket.resetAfterSeconds && Number.isFinite(bucket.resetAfterSeconds)) {
    return new Date(observedAt + bucket.resetAfterSeconds * 1000);
  }
  return undefined;
}

function formatQuotaBucket(theme: any, label: "5h" | "7d", bucket: QuotaBucket | undefined, quotaKnown: boolean): string {
  if (!bucket) {
    return quotaKnown
      ? `${label}:${theme.fg("muted", "n/a")} ${theme.fg("muted", "(not reported)")}`
      : `${label}:${theme.fg("warning", "pending")} ${theme.fg("muted", "(run /status-refresh)")}`;
  }
  const date = resetDate(bucket, quotaState?.updatedAt ?? Date.now());
  const expired = date !== undefined && date.getTime() <= Date.now();
  const pct = colorPercent(theme, expired ? undefined : bucket.percent, "%", "pending");
  const reset = expired
    ? "refresh pending"
    : date
      ? (label === "7d" ? formatWeekdayHHMM(date) : formatTimeHHMM(date))
      : "unknown";
  return `${label}:${pct} ${theme.fg("muted", `(resets ${reset})`)}`;
}

function normalizeLimitName(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]/g, "");
}

function quotaBucketsForModel(modelId: string | undefined): Partial<Record<"5h" | "7d", QuotaBucket>> {
  if (!quotaState) return {};
  const normalizedModel = normalizeLimitName(modelId ?? "");
  if (normalizedModel.includes("spark")) {
    for (const buckets of Object.values(quotaState.families ?? {})) {
      const limitName = buckets["5h"]?.limitName ?? buckets["7d"]?.limitName ?? "";
      const normalizedLimit = normalizeLimitName(limitName);
      if (normalizedLimit && (normalizedModel.includes(normalizedLimit) || normalizedLimit.includes(normalizedModel))) {
        return buckets;
      }
    }
    return {};
  }
  return quotaState.buckets;
}

function coerceNumber(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return undefined;
}

function header(headers: Record<string, string>, name: string): string | undefined {
  return headers[name.toLowerCase()];
}

function captureOpenAICodexQuota(headersIn: Record<string, string>): boolean {
  const headers: Record<string, string> = {};
  for (const [key, value] of Object.entries(headersIn)) headers[key.toLowerCase()] = value;

  type Candidate = QuotaBucket & { family: string; role: "primary" | "secondary" };
  const candidates: Candidate[] = [];

  // Supports both root headers (x-codex-primary-...) and named families such as
  // x-codex-bengalfox-primary-... used by Codex subscription limits.
  for (const [key] of Object.entries(headers)) {
    const match = key.match(/^x-codex(?:-([a-z0-9]+))?-(primary|secondary)-window-minutes$/i);
    if (!match) continue;
    const family = match[1] ?? "";
    const role = match[2] as "primary" | "secondary";
    const prefix = family ? `x-codex-${family}-${role}` : `x-codex-${role}`;
    const minutes = coerceNumber(header(headers, `${prefix}-window-minutes`));
    if (minutes !== 300 && minutes !== 10080) continue;
    candidates.push({
      label: minutes === 300 ? "5h" : "7d",
      family,
      role,
      limitName: family ? header(headers, `x-codex-${family}-limit-name`) : header(headers, "x-codex-active-limit"),
      percent: coerceNumber(header(headers, `${prefix}-used-percent`)),
      resetAt: coerceNumber(header(headers, `${prefix}-reset-at`)),
      resetAfterSeconds: coerceNumber(header(headers, `${prefix}-reset-after-seconds`)),
    });
  }

  // Keep both buckets in the same quota family. Root headers describe the
  // active model/account limit; named families (for example a Spark-specific
  // allowance) must not be mixed into that pair.
  const rootCandidates = candidates.filter((candidate) => candidate.family === "");
  let selected = rootCandidates;
  if (selected.length === 0 && candidates.length > 0) {
    const counts = new Map<string, number>();
    for (const candidate of candidates) counts.set(candidate.family, (counts.get(candidate.family) ?? 0) + 1);
    const family = [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
    selected = candidates.filter((candidate) => candidate.family === family);
  }

  const families: Record<string, Partial<Record<"5h" | "7d", QuotaBucket>>> = {};
  for (const candidate of candidates) {
    if (!candidate.family) continue;
    (families[candidate.family] ??= {})[candidate.label] = candidate;
  }

  const next: QuotaState = {
    updatedAt: Date.now(),
    buckets: {
      "5h": selected.find((candidate) => candidate.label === "5h"),
      "7d": selected.find((candidate) => candidate.label === "7d"),
    },
    families,
    activeLimit: header(headers, "x-codex-active-limit"),
    planType: header(headers, "x-codex-plan-type"),
  };

  if (next.buckets["5h"] || next.buckets["7d"]) {
    quotaState = next;
    saveQuotaCache(next);
    requestFooterRender?.();
    return true;
  }
  return false;
}

async function queryCodexQuota(ctx: any): Promise<boolean> {
  const auth = await ctx.modelRegistry?.getProviderAuth?.("openai-codex");
  const token = auth?.auth?.apiKey;
  if (!token || typeof token !== "string") return false;

  const claims = decodeJwtPayload(token);
  const accountId = claims?.["https://api.openai.com/auth"]?.chatgpt_account_id;
  if (!accountId) return false;

  const response = await fetch("https://chatgpt.com/backend-api/codex/responses", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${token}`,
      "chatgpt-account-id": String(accountId),
      "originator": "pi",
      "User-Agent": "pi-coding-agent",
      "OpenAI-Beta": "responses=experimental",
      "accept": "text/event-stream",
      "content-type": "application/json",
    },
    body: JSON.stringify({
      model: ctx.model?.provider === "openai-codex" ? ctx.model.id : "gpt-5.4-mini",
      store: false,
      stream: true,
      instructions: "Return the single word ok.",
      input: [{ role: "user", content: [{ type: "input_text", text: "ok" }] }],
      text: { verbosity: "low" },
    }),
    signal: AbortSignal.timeout(15_000),
  });

  const headers: Record<string, string> = {};
  response.headers.forEach((value, key) => {
    headers[key] = value;
  });
  const captured = response.ok && captureOpenAICodexQuota(headers);
  await response.body?.cancel().catch(() => undefined);
  return captured;
}

function decodeJwtPayload(token: string): Record<string, any> | undefined {
  const parts = token.split(".");
  if (parts.length < 2 || !parts[1]) return undefined;
  try {
    const base64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, "=");
    return JSON.parse(Buffer.from(padded, "base64").toString("utf8"));
  } catch {
    return undefined;
  }
}

function readAuthJson(): Record<string, any> {
  try {
    if (!existsSync(AUTH_PATH)) return {};
    const mtimeMs = statSync(AUTH_PATH).mtimeMs;
    if (authCache?.mtimeMs === mtimeMs) return authCache.value;
    const value = JSON.parse(readFileSync(AUTH_PATH, "utf8"));
    authCache = { mtimeMs, value };
    return value;
  } catch {
    return {};
  }
}

function accountLabel(provider: string | undefined, ctx: any): string {
  if (!provider) return "unknown";
  if (provider === "ibm-services-essentials") return `IBM:${process.env.ICA_OP_KEY_NAME || "ICA_CODEX"}`;

  const auth = readAuthJson()[provider];
  if (auth?.type === "oauth") {
    const claims = typeof auth.access === "string" ? decodeJwtPayload(auth.access) : undefined;
    const openaiAuth = claims?.["https://api.openai.com/auth"];
    const profile = claims?.["https://api.openai.com/profile"];
    if (profile?.email) return String(profile.email);
    if (profile?.name) return String(profile.name);
    if (openaiAuth?.chatgpt_account_id) return `acct:${String(openaiAuth.chatgpt_account_id).slice(0, 8)}`;
    if (auth.accountId) return `acct:${String(auth.accountId).slice(0, 8)}`;
    return `${provider}:oauth`;
  }

  const status = ctx.modelRegistry?.getProviderAuthStatus?.(provider);
  if (status?.configured) return status.label || status.source || "configured";
  return provider;
}

function contextPercent(ctx: any): { percent?: number; contextWindow: number } {
  const usage = ctx.getContextUsage?.();
  return {
    percent: usage?.percent ?? undefined,
    contextWindow: usage?.contextWindow ?? ctx.model?.contextWindow ?? 0,
  };
}

function usageStats(ctx: any) {
  const totals = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, latestCacheHitRate: undefined as number | undefined };
  for (const entry of ctx.sessionManager.getEntries()) {
    const msg = entry.type === "message" ? entry.message : undefined;
    const usage = msg?.role === "assistant" || msg?.role === "toolResult" ? msg.usage : entry.usage;
    if (!usage) continue;
    totals.input += usage.input ?? 0;
    totals.output += usage.output ?? 0;
    totals.cacheRead += usage.cacheRead ?? 0;
    totals.cacheWrite += usage.cacheWrite ?? 0;
    totals.cost += usage.cost?.total ?? 0;
    if (msg?.role === "assistant") {
      const prompt = (usage.input ?? 0) + (usage.cacheRead ?? 0) + (usage.cacheWrite ?? 0);
      totals.latestCacheHitRate = prompt > 0 ? ((usage.cacheRead ?? 0) / prompt) * 100 : undefined;
    }
  }
  return totals;
}

function boldLabel(theme: any, text: string): string {
  return theme.bold(theme.fg("accent", text));
}

function thinkingText(theme: any, level: string): string {
  const colorByLevel: Record<string, string> = {
    off: "muted",
    minimal: "thinkingMinimal",
    low: "thinkingLow",
    medium: "thinkingMedium",
    high: "thinkingHigh",
    xhigh: "thinkingXhigh",
    max: "thinkingXhigh",
  };
  const color = colorByLevel[level] || "accent";
  try {
    return theme.bold(theme.fg(color, level));
  } catch {
    return theme.bold(theme.fg("accent", level));
  }
}

function installFooter(ctx: any): void {
  ctx.ui.setFooter((tui: any, theme: any, footerData: any) => {
    requestFooterRender = () => tui.requestRender();
    const unsubscribeBranch = footerData.onBranchChange(() => tui.requestRender());

    return {
      dispose() {
        unsubscribeBranch?.();
        if (requestFooterRender) requestFooterRender = undefined;
      },
      invalidate() {},
      render(width: number): string[] {
        const model = ctx.model;
        const modelText = model ? `${model.provider}/${model.id}` : "no-model";
        const thinking = ctx.thinkingLevel || (model?.reasoning ? "off" : "off");

        let dir = formatCwd(ctx.sessionManager.getCwd());
        const branch = footerData.getGitBranch();
        if (branch) dir += ` (${branch})`;
        const sessionName = ctx.sessionManager.getSessionName?.();
        if (sessionName) dir += ` • ${sessionName}`;

        const acct = accountLabel(model?.provider, ctx);
        const ctxInfo = contextPercent(ctx);
        const ctxPct = colorPercent(theme, ctxInfo.percent, "%", "pending");
        const showCodexQuota = model?.provider === "openai-codex";
        const showIbmCredits = model?.provider === "ibm-services-essentials";
        const quota = quotaBucketsForModel(model?.id);
        const quotaKnown = quotaState !== undefined && (!normalizeLimitName(model?.id ?? "").includes("spark") || Object.keys(quota).length > 0);
        const quotaText = `${theme.fg("text", "{")}${formatQuotaBucket(theme, "5h", quota["5h"], quotaKnown)} ${formatQuotaBucket(theme, "7d", quota["7d"], quotaKnown)}${theme.fg("text", "}")}`;

        const requestedParts = [
          `${theme.fg("text", "[")}${boldLabel(theme, modelText)} ${theme.fg("accent", "🧠")}${thinkingText(theme, thinking)}${theme.fg("text", "]")}`,
          `${theme.fg("accent", "📁")} ${theme.fg("text", dir)}`,
          `${theme.fg("accent", "👤")} ${theme.fg("text", acct)}`,
          `${boldLabel(theme, "ctx:")}${ctxPct}`,
        ];
        if (showCodexQuota) requestedParts.push(quotaText);
        if (showIbmCredits) requestedParts.push(formatIbmCredits(theme));
        const requestedLine = requestedParts.join(theme.fg("muted", " | "));

        const stats = usageStats(ctx);
        const statsParts = [
          `${boldLabel(theme, "tokens")}`,
          `↑${formatTokens(stats.input)}`,
          `↓${formatTokens(stats.output)}`,
        ];
        if (stats.cacheRead) statsParts.push(`R${formatTokens(stats.cacheRead)}`);
        if (stats.cacheWrite) statsParts.push(`W${formatTokens(stats.cacheWrite)}`);
        if ((stats.cacheRead || stats.cacheWrite) && stats.latestCacheHitRate !== undefined) {
          statsParts.push(`CH${colorPercent(theme, stats.latestCacheHitRate)}`);
        }
        const authStatus = model ? ctx.modelRegistry?.getProviderAuthStatus?.(model.provider) : undefined;
        const usingOAuth = model ? ctx.modelRegistry?.isUsingOAuth?.(model) === true : false;
        const provider = model ? ctx.modelRegistry?.getProvider?.(model.provider) : undefined;
        const usingSubscription = usingOAuth && provider?.auth?.oauth?.isSubscription === true;
        if (stats.cost) {
          statsParts.push(`$${stats.cost.toFixed(3)}${usingSubscription ? " est (sub)" : ""}`);
        }
        statsParts.push(`${formatTokens(ctxInfo.contextWindow)} window`);
        if (authStatus?.configured) {
          const source = authStatus.label || authStatus.source || "configured";
          statsParts.push(`auth:${source}${usingOAuth ? "/oauth" : "/api-key"}`);
        }
        const statusLine = statsParts.map((part) => part.includes("\x1b[") ? part : theme.fg("text", part)).join(" ");

        const lines: string[] = [];
        if (visibleWidth(requestedLine) <= width) {
          lines.push(requestedLine);
        } else {
          const compactModel = `${theme.fg("text", "[")}${boldLabel(theme, model?.id || "no-model")} ${theme.fg("accent", "🧠")}${thinkingText(theme, thinking)}${theme.fg("text", "]")}`;
          const compactLine = [
            compactModel,
            `${theme.fg("accent", "📁")} ${theme.fg("text", dir)}`,
            `${theme.fg("accent", "👤")} ${theme.fg("text", acct)}`,
          ].join(theme.fg("muted", " | "));
          lines.push(truncateToWidth(compactLine, width, theme.fg("muted", "…")));
          const contextAndQuota = showCodexQuota
            ? `${boldLabel(theme, "ctx:")}${ctxPct} ${quotaText}`
            : showIbmCredits
              ? `${boldLabel(theme, "ctx:")}${ctxPct} ${formatIbmCredits(theme)}`
              : `${boldLabel(theme, "ctx:")}${ctxPct}`;
          lines.push(truncateToWidth(contextAndQuota, width, theme.fg("muted", "…")));
        }

        lines.push(truncateToWidth(statusLine, width, theme.fg("muted", "…")));

        const extensionStatuses = footerData.getExtensionStatuses();
        if (extensionStatuses.size > 0) {
          const statusText = Array.from(extensionStatuses.entries())
            .sort(([a]: [string, string], [b]: [string, string]) => a.localeCompare(b))
            .map(([, text]: [string, string]) => text.replace(/[\r\n\t]/g, " ").replace(/ +/g, " ").trim())
            .join(" ");
          lines.push(truncateToWidth(theme.fg("text", statusText), width, theme.fg("muted", "…")));
        }

        return lines;
      },
    };
  });
}

function shouldRenderStatusLine(ctx: any): boolean {
  return ctx.mode === "tui" || ctx.mode === "rpc";
}

export default function enhancedStatusLine(pi: ExtensionAPI) {
  pi.registerCommand("status-refresh", {
    description: "Refresh quota or credit data for the active provider",
    handler: async (_args, ctx) => {
      try {
        const isIbm = ctx.model?.provider === "ibm-services-essentials";
        const refreshed = isIbm ? await queryIbmCredits() : await queryCodexQuota(ctx);
        const label = isIbm ? "IBM credit" : "Codex quota";
        ctx.ui.notify(refreshed ? `${label} status refreshed` : `${label} data was unavailable`, refreshed ? "info" : "warning");
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        ctx.ui.notify(`Status refresh failed: ${message}`, "error");
      }
    },
  });

  pi.on("session_start", (_event, ctx) => {
    if (!shouldRenderStatusLine(ctx)) return;
    installFooter(ctx);
    if (ctx.model?.provider === "ibm-services-essentials" && Date.now() - lastIbmBudgetRefreshAt > 5 * 60_000) {
      void queryIbmCredits().catch(() => false);
    }
  });

  pi.on("model_select", (event) => {
    if (event.model.provider === "ibm-services-essentials" && Date.now() - lastIbmBudgetRefreshAt > 5 * 60_000) {
      void queryIbmCredits().catch(() => false);
    }
    requestFooterRender?.();
  });

  pi.on("after_provider_response", (event, ctx) => {
    if (event.status < 200 || event.status >= 300) return;
    if (ctx.model?.provider === "openai-codex") captureOpenAICodexQuota(event.headers ?? {});
    if (ctx.model?.provider === "ibm-services-essentials") captureIbmCredits(event.headers ?? {});
  });
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, resolve, sep, isAbsolute } from "node:path";
import { homedir } from "node:os";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

const AGENT_DIR = process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent");
const AUTH_PATH = join(AGENT_DIR, "auth.json");
const QUOTA_CACHE_PATH = join(AGENT_DIR, "status-line-quota.json");
const IBM_CREDITS_CACHE_PATH = join(AGENT_DIR, "status-line-ibm-credits.json");
const IBM_TEAM_ID = process.env.IBM_SERVICES_ESSENTIALS_TEAM_ID || "6a8d8b68f91e25193bbd853d";
const IBM_BUDGET_URL = `https://servicesessentials.ibm.com/services/integrations/team/${IBM_TEAM_ID}/budget`;
const IBM_API_KEY_HELPER = join(AGENT_DIR, "bin", "ibm-services-essentials-api-key");
const IBM_DEFAULT_MAX_CREDITS = Number(process.env.IBM_SERVICES_ESSENTIALS_MAX_CREDITS || 500);

type QuotaBucket = {
  label: "5h" | "7d";
  percent?: number;
  resetAt?: number;
  resetAfterSeconds?: number;
  family?: string;
  limitName?: string;
};

type QuotaState = {
  updatedAt: number;
  buckets: Partial<Record<"5h" | "7d", QuotaBucket>>;
  families?: Record<string, Partial<Record<"5h" | "7d", QuotaBucket>>>;
  activeLimit?: string;
  planType?: string;
};

type IbmCreditsState = {
  updatedAt: number;
  teamId?: string;
  spendCredits: number;
  maxCredits: number;
  softCredits?: number;
  resetAt?: number;
  blocked?: boolean;
  source: "budget" | "response-header";
};

let quotaState: QuotaState | undefined = loadQuotaCache();
let ibmCreditsState: IbmCreditsState | undefined = loadIbmCreditsCache();
let requestFooterRender: (() => void) | undefined;
let lastIbmBudgetRefreshAt = 0;
let authCache: { mtimeMs: number; value: Record<string, any> } | undefined;

function loadQuotaCache(): QuotaState | undefined {
  try {
    if (!existsSync(QUOTA_CACHE_PATH)) return undefined;
    const parsed = JSON.parse(readFileSync(QUOTA_CACHE_PATH, "utf8"));
    if (!parsed || typeof parsed !== "object") return undefined;
    if (typeof parsed.updatedAt !== "number") return undefined;
    const state = parsed as QuotaState;
    const fiveHour = state.buckets?.["5h"];
    const sevenDay = state.buckets?.["7d"];
    // Older cache versions could combine a model-specific 5h quota with the
    // account-wide 7d quota. Never present percentages from different families
    // as if they form one limit pair.
    if (fiveHour && sevenDay && (fiveHour.family ?? "") !== (sevenDay.family ?? "")) {
      delete state.buckets["5h"];
    }
    return state;
  } catch {
    return undefined;
  }
}

function saveQuotaCache(state: QuotaState): void {
  try {
    writeFileSync(QUOTA_CACHE_PATH, JSON.stringify(state, null, 2) + "\n", { mode: 0o600 });
  } catch {
    // Best-effort cache only; footer should never fail because of this.
  }
}

function loadIbmCreditsCache(): IbmCreditsState | undefined {
  try {
    if (!existsSync(IBM_CREDITS_CACHE_PATH)) return undefined;
    const state = JSON.parse(readFileSync(IBM_CREDITS_CACHE_PATH, "utf8")) as IbmCreditsState;
    if (!Number.isFinite(state.updatedAt) || !Number.isFinite(state.spendCredits) || !Number.isFinite(state.maxCredits)) return undefined;
    return state;
  } catch {
    return undefined;
  }
}

function saveIbmCreditsCache(state: IbmCreditsState): void {
  try {
    writeFileSync(IBM_CREDITS_CACHE_PATH, JSON.stringify(state, null, 2) + "\n", { mode: 0o600 });
  } catch {
    // Best-effort cache only; footer should never fail because of this.
  }
}

function readIbmApiKey(): string | undefined {
  try {
    const key = execFileSync(IBM_API_KEY_HELPER, {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
      timeout: 10_000,
    }).trim();
    return key || undefined;
  } catch {
    return undefined;
  }
}

function storeIbmCredits(state: IbmCreditsState): void {
  ibmCreditsState = state;
  saveIbmCreditsCache(state);
  requestFooterRender?.();
}

async function queryIbmCredits(signal?: AbortSignal): Promise<boolean> {
  const apiKey = readIbmApiKey();
  if (!apiKey) return false;
  lastIbmBudgetRefreshAt = Date.now();

  const response = await fetch(IBM_BUDGET_URL, {
    headers: { "Accept": "application/json", "Authorization": `Bearer ${apiKey}` },
    signal: signal ?? AbortSignal.timeout(15_000),
  });
  if (!response.ok) return false;

  const payload = await response.json() as Record<string, unknown>;
  const spendCredits = coerceNumber(payload.advantageCredits) ?? coerceNumber(payload.spendUsd);
  const maxCredits = coerceNumber(payload.maxAdvantageCredits) ?? coerceNumber(payload.maxBudgetUsd);
  if (spendCredits === undefined || maxCredits === undefined) return false;

  storeIbmCredits({
    updatedAt: Date.now(),
    teamId: typeof payload.teamId === "string" ? payload.teamId : IBM_TEAM_ID,
    spendCredits,
    maxCredits,
    softCredits: coerceNumber(payload.softAdvantageCredits) ?? coerceNumber(payload.softBudgetUsd),
    resetAt: coerceNumber(payload.budgetResetAtEpochSeconds),
    blocked: typeof payload.blocked === "boolean" ? payload.blocked : undefined,
    source: "budget",
  });
  return true;
}

function captureIbmCredits(headersIn: Record<string, string>): boolean {
  const headers: Record<string, string> = {};
  for (const [key, value] of Object.entries(headersIn)) headers[key.toLowerCase()] = value;
  const spendCredits = coerceNumber(headers["x-litellm-key-spend"]);
  if (spendCredits === undefined) return false;

  storeIbmCredits({
    updatedAt: Date.now(),
    teamId: ibmCreditsState?.teamId ?? IBM_TEAM_ID,
    spendCredits,
    maxCredits: ibmCreditsState?.maxCredits ?? IBM_DEFAULT_MAX_CREDITS,
    softCredits: ibmCreditsState?.softCredits,
    resetAt: ibmCreditsState?.resetAt,
    blocked: ibmCreditsState?.blocked,
    source: ibmCreditsState?.source === "budget" ? "budget" : "response-header",
  });
  return true;
}

function formatCwd(cwd: string): string {
  const home = process.env.HOME || process.env.USERPROFILE;
  if (!home) return cwd;
  const resolvedCwd = resolve(cwd);
  const resolvedHome = resolve(home);
  const rel = relative(resolvedHome, resolvedCwd);
  const inside = rel === "" || (rel !== ".." && !rel.startsWith(`..${sep}`) && !isAbsolute(rel));
  return inside ? (rel === "" ? "~" : `~${sep}${rel}`) : cwd;
}

function formatCredits(value: number): string {
  if (!Number.isFinite(value)) return "?";
  if (Math.abs(value) >= 1_000) return value.toLocaleString(undefined, { maximumFractionDigits: 0 });
  return value.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}

function formatIbmCredits(theme: any): string {
  if (!ibmCreditsState) return `${boldLabel(theme, "credits:")}${theme.fg("warning", "pending")}`;
  const available = Math.max(0, ibmCreditsState.maxCredits - ibmCreditsState.spendCredits);
  const ratio = ibmCreditsState.maxCredits > 0 ? available / ibmCreditsState.maxCredits : 0;
  const color = ibmCreditsState.blocked || ratio <= 0.1 ? "error" : ratio <= 0.2 ? "warning" : "success";
  const approximate = ibmCreditsState.source === "response-header" ? "~" : "";
  const reset = ibmCreditsState.resetAt && ibmCreditsState.resetAt * 1000 > Date.now()
    ? ` ${theme.fg("muted", `(resets ${formatWeekdayHHMM(new Date(ibmCreditsState.resetAt * 1000))})`)}`
    : "";
  return `${boldLabel(theme, "credits:")}${theme.fg(color, `${approximate}${formatCredits(available)}/${formatCredits(ibmCreditsState.maxCredits)}`)}${reset}`;
}

function formatTokens(count: number): string {
  if (!Number.isFinite(count) || count <= 0) return "0";
  if (count < 1_000) return String(Math.round(count));
  if (count < 10_000) return `${(count / 1_000).toFixed(1)}k`;
  if (count < 1_000_000) return `${Math.round(count / 1_000)}k`;
  if (count < 10_000_000) return `${(count / 1_000_000).toFixed(1)}M`;
  return `${Math.round(count / 1_000_000)}M`;
}

function colorPercent(theme: any, value: number | undefined, suffix = "%", unknownLabel = `?${suffix}`): string {
  if (value === undefined || !Number.isFinite(value)) return theme.fg("warning", unknownLabel);
  const text = `${Math.max(0, Math.min(999, value)).toFixed(0)}${suffix}`;
  if (value <= 50) return theme.fg("success", text);
  if (value <= 80) return theme.fg("warning", text);
  return theme.fg("error", text);
}

function formatTimeHHMM(date: Date): string {
  return date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit", hour12: false });
}

function formatWeekdayHHMM(date: Date): string {
  return `${date.toLocaleDateString(undefined, { weekday: "short" })} ${formatTimeHHMM(date)}`;
}

function resetDate(bucket: QuotaBucket, observedAt: number): Date | undefined {
  if (bucket.resetAt && Number.isFinite(bucket.resetAt)) return new Date(bucket.resetAt * 1000);
  if (bucket.resetAfterSeconds && Number.isFinite(bucket.resetAfterSeconds)) {
    return new Date(observedAt + bucket.resetAfterSeconds * 1000);
  }
  return undefined;
}

function formatQuotaBucket(theme: any, label: "5h" | "7d", bucket: QuotaBucket | undefined, quotaKnown: boolean): string {
  if (!bucket) {
    return quotaKnown
      ? `${label}:${theme.fg("muted", "n/a")} ${theme.fg("muted", "(not reported)")}`
      : `${label}:${theme.fg("warning", "pending")} ${theme.fg("muted", "(run /status-refresh)")}`;
  }
  const date = resetDate(bucket, quotaState?.updatedAt ?? Date.now());
  const expired = date !== undefined && date.getTime() <= Date.now();
  const pct = colorPercent(theme, expired ? undefined : bucket.percent, "%", "pending");
  const reset = expired
    ? "refresh pending"
    : date
      ? (label === "7d" ? formatWeekdayHHMM(date) : formatTimeHHMM(date))
      : "unknown";
  return `${label}:${pct} ${theme.fg("muted", `(resets ${reset})`)}`;
}

function normalizeLimitName(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]/g, "");
}

function quotaBucketsForModel(modelId: string | undefined): Partial<Record<"5h" | "7d", QuotaBucket>> {
  if (!quotaState) return {};
  const normalizedModel = normalizeLimitName(modelId ?? "");
  if (normalizedModel.includes("spark")) {
    for (const buckets of Object.values(quotaState.families ?? {})) {
      const limitName = buckets["5h"]?.limitName ?? buckets["7d"]?.limitName ?? "";
      const normalizedLimit = normalizeLimitName(limitName);
      if (normalizedLimit && (normalizedModel.includes(normalizedLimit) || normalizedLimit.includes(normalizedModel))) {
        return buckets;
      }
    }
    return {};
  }
  return quotaState.buckets;
}

function coerceNumber(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return undefined;
}

function header(headers: Record<string, string>, name: string): string | undefined {
  return headers[name.toLowerCase()];
}

function captureOpenAICodexQuota(headersIn: Record<string, string>): boolean {
  const headers: Record<string, string> = {};
  for (const [key, value] of Object.entries(headersIn)) headers[key.toLowerCase()] = value;

  type Candidate = QuotaBucket & { family: string; role: "primary" | "secondary" };
  const candidates: Candidate[] = [];

  // Supports both root headers (x-codex-primary-...) and named families such as
  // x-codex-bengalfox-primary-... used by Codex subscription limits.
  for (const [key] of Object.entries(headers)) {
    const match = key.match(/^x-codex(?:-([a-z0-9]+))?-(primary|secondary)-window-minutes$/i);
    if (!match) continue;
    const family = match[1] ?? "";
    const role = match[2] as "primary" | "secondary";
    const prefix = family ? `x-codex-${family}-${role}` : `x-codex-${role}`;
    const minutes = coerceNumber(header(headers, `${prefix}-window-minutes`));
    if (minutes !== 300 && minutes !== 10080) continue;
    candidates.push({
      label: minutes === 300 ? "5h" : "7d",
      family,
      role,
      limitName: family ? header(headers, `x-codex-${family}-limit-name`) : header(headers, "x-codex-active-limit"),
      percent: coerceNumber(header(headers, `${prefix}-used-percent`)),
      resetAt: coerceNumber(header(headers, `${prefix}-reset-at`)),
      resetAfterSeconds: coerceNumber(header(headers, `${prefix}-reset-after-seconds`)),
    });
  }

  // Keep both buckets in the same quota family. Root headers describe the
  // active model/account limit; named families (for example a Spark-specific
  // allowance) must not be mixed into that pair.
  const rootCandidates = candidates.filter((candidate) => candidate.family === "");
  let selected = rootCandidates;
  if (selected.length === 0 && candidates.length > 0) {
    const counts = new Map<string, number>();
    for (const candidate of candidates) counts.set(candidate.family, (counts.get(candidate.family) ?? 0) + 1);
    const family = [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
    selected = candidates.filter((candidate) => candidate.family === family);
  }

  const families: Record<string, Partial<Record<"5h" | "7d", QuotaBucket>>> = {};
  for (const candidate of candidates) {
    if (!candidate.family) continue;
    (families[candidate.family] ??= {})[candidate.label] = candidate;
  }

  const next: QuotaState = {
    updatedAt: Date.now(),
    buckets: {
      "5h": selected.find((candidate) => candidate.label === "5h"),
      "7d": selected.find((candidate) => candidate.label === "7d"),
    },
    families,
    activeLimit: header(headers, "x-codex-active-limit"),
    planType: header(headers, "x-codex-plan-type"),
  };

  if (next.buckets["5h"] || next.buckets["7d"]) {
    quotaState = next;
    saveQuotaCache(next);
    requestFooterRender?.();
    return true;
  }
  return false;
}

async function queryCodexQuota(ctx: any): Promise<boolean> {
  const auth = await ctx.modelRegistry?.getProviderAuth?.("openai-codex");
  const token = auth?.auth?.apiKey;
  if (!token || typeof token !== "string") return false;

  const claims = decodeJwtPayload(token);
  const accountId = claims?.["https://api.openai.com/auth"]?.chatgpt_account_id;
  if (!accountId) return false;

  const response = await fetch("https://chatgpt.com/backend-api/codex/responses", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${token}`,
      "chatgpt-account-id": String(accountId),
      "originator": "pi",
      "User-Agent": "pi-coding-agent",
      "OpenAI-Beta": "responses=experimental",
      "accept": "text/event-stream",
      "content-type": "application/json",
    },
    body: JSON.stringify({
      model: ctx.model?.provider === "openai-codex" ? ctx.model.id : "gpt-5.4-mini",
      store: false,
      stream: true,
      instructions: "Return the single word ok.",
      input: [{ role: "user", content: [{ type: "input_text", text: "ok" }] }],
      text: { verbosity: "low" },
    }),
    signal: AbortSignal.timeout(15_000),
  });

  const headers: Record<string, string> = {};
  response.headers.forEach((value, key) => {
    headers[key] = value;
  });
  const captured = response.ok && captureOpenAICodexQuota(headers);
  await response.body?.cancel().catch(() => undefined);
  return captured;
}

function decodeJwtPayload(token: string): Record<string, any> | undefined {
  const parts = token.split(".");
  if (parts.length < 2 || !parts[1]) return undefined;
  try {
    const base64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, "=");
    return JSON.parse(Buffer.from(padded, "base64").toString("utf8"));
  } catch {
    return undefined;
  }
}

function readAuthJson(): Record<string, any> {
  try {
    if (!existsSync(AUTH_PATH)) return {};
    const mtimeMs = statSync(AUTH_PATH).mtimeMs;
    if (authCache?.mtimeMs === mtimeMs) return authCache.value;
    const value = JSON.parse(readFileSync(AUTH_PATH, "utf8"));
    authCache = { mtimeMs, value };
    return value;
  } catch {
    return {};
  }
}

function accountLabel(provider: string | undefined, ctx: any): string {
  if (!provider) return "unknown";
  if (provider === "ibm-services-essentials") return `IBM:${process.env.ICA_OP_KEY_NAME || "ICA_CODEX"}`;

  const auth = readAuthJson()[provider];
  if (auth?.type === "oauth") {
    const claims = typeof auth.access === "string" ? decodeJwtPayload(auth.access) : undefined;
    const openaiAuth = claims?.["https://api.openai.com/auth"];
    const profile = claims?.["https://api.openai.com/profile"];
    if (profile?.email) return String(profile.email);
    if (profile?.name) return String(profile.name);
    if (openaiAuth?.chatgpt_account_id) return `acct:${String(openaiAuth.chatgpt_account_id).slice(0, 8)}`;
    if (auth.accountId) return `acct:${String(auth.accountId).slice(0, 8)}`;
    return `${provider}:oauth`;
  }

  const status = ctx.modelRegistry?.getProviderAuthStatus?.(provider);
  if (status?.configured) return status.label || status.source || "configured";
  return provider;
}

function contextPercent(ctx: any): { percent?: number; contextWindow: number } {
  const usage = ctx.getContextUsage?.();
  return {
    percent: usage?.percent ?? undefined,
    contextWindow: usage?.contextWindow ?? ctx.model?.contextWindow ?? 0,
  };
}

function usageStats(ctx: any) {
  const totals = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, latestCacheHitRate: undefined as number | undefined };
  for (const entry of ctx.sessionManager.getEntries()) {
    const msg = entry.type === "message" ? entry.message : undefined;
    const usage = msg?.role === "assistant" || msg?.role === "toolResult" ? msg.usage : entry.usage;
    if (!usage) continue;
    totals.input += usage.input ?? 0;
    totals.output += usage.output ?? 0;
    totals.cacheRead += usage.cacheRead ?? 0;
    totals.cacheWrite += usage.cacheWrite ?? 0;
    totals.cost += usage.cost?.total ?? 0;
    if (msg?.role === "assistant") {
      const prompt = (usage.input ?? 0) + (usage.cacheRead ?? 0) + (usage.cacheWrite ?? 0);
      totals.latestCacheHitRate = prompt > 0 ? ((usage.cacheRead ?? 0) / prompt) * 100 : undefined;
    }
  }
  return totals;
}

function boldLabel(theme: any, text: string): string {
  return theme.bold(theme.fg("accent", text));
}

function thinkingText(theme: any, level: string): string {
  const colorByLevel: Record<string, string> = {
    off: "muted",
    minimal: "thinkingMinimal",
    low: "thinkingLow",
    medium: "thinkingMedium",
    high: "thinkingHigh",
    xhigh: "thinkingXhigh",
    max: "thinkingXhigh",
  };
  const color = colorByLevel[level] || "accent";
  try {
    return theme.bold(theme.fg(color, level));
  } catch {
    return theme.bold(theme.fg("accent", level));
  }
}

function installFooter(ctx: any): void {
  ctx.ui.setFooter((tui: any, theme: any, footerData: any) => {
    requestFooterRender = () => tui.requestRender();
    const unsubscribeBranch = footerData.onBranchChange(() => tui.requestRender());

    return {
      dispose() {
        unsubscribeBranch?.();
        if (requestFooterRender) requestFooterRender = undefined;
      },
      invalidate() {},
      render(width: number): string[] {
        const model = ctx.model;
        const modelText = model ? `${model.provider}/${model.id}` : "no-model";
        const thinking = ctx.thinkingLevel || (model?.reasoning ? "off" : "off");

        let dir = formatCwd(ctx.sessionManager.getCwd());
        const branch = footerData.getGitBranch();
        if (branch) dir += ` (${branch})`;
        const sessionName = ctx.sessionManager.getSessionName?.();
        if (sessionName) dir += ` • ${sessionName}`;

        const acct = accountLabel(model?.provider, ctx);
        const ctxInfo = contextPercent(ctx);
        const ctxPct = colorPercent(theme, ctxInfo.percent, "%", "pending");
        const showCodexQuota = model?.provider === "openai-codex";
        const showIbmCredits = model?.provider === "ibm-services-essentials";
        const quota = quotaBucketsForModel(model?.id);
        const quotaKnown = quotaState !== undefined && (!normalizeLimitName(model?.id ?? "").includes("spark") || Object.keys(quota).length > 0);
        const quotaText = `${theme.fg("text", "{")}${formatQuotaBucket(theme, "5h", quota["5h"], quotaKnown)} ${formatQuotaBucket(theme, "7d", quota["7d"], quotaKnown)}${theme.fg("text", "}")}`;

        const requestedParts = [
          `${theme.fg("text", "[")}${boldLabel(theme, modelText)} ${theme.fg("accent", "🧠")}${thinkingText(theme, thinking)}${theme.fg("text", "]")}`,
          `${theme.fg("accent", "📁")} ${theme.fg("text", dir)}`,
          `${theme.fg("accent", "👤")} ${theme.fg("text", acct)}`,
          `${boldLabel(theme, "ctx:")}${ctxPct}`,
        ];
        if (showCodexQuota) requestedParts.push(quotaText);
        if (showIbmCredits) requestedParts.push(formatIbmCredits(theme));
        const requestedLine = requestedParts.join(theme.fg("muted", " | "));

        const stats = usageStats(ctx);
        const statsParts = [
          `${boldLabel(theme, "tokens")}`,
          `↑${formatTokens(stats.input)}`,
          `↓${formatTokens(stats.output)}`,
        ];
        if (stats.cacheRead) statsParts.push(`R${formatTokens(stats.cacheRead)}`);
        if (stats.cacheWrite) statsParts.push(`W${formatTokens(stats.cacheWrite)}`);
        if ((stats.cacheRead || stats.cacheWrite) && stats.latestCacheHitRate !== undefined) {
          statsParts.push(`CH${colorPercent(theme, stats.latestCacheHitRate)}`);
        }
        const authStatus = model ? ctx.modelRegistry?.getProviderAuthStatus?.(model.provider) : undefined;
        const usingOAuth = model ? ctx.modelRegistry?.isUsingOAuth?.(model) === true : false;
        const provider = model ? ctx.modelRegistry?.getProvider?.(model.provider) : undefined;
        const usingSubscription = usingOAuth && provider?.auth?.oauth?.isSubscription === true;
        if (stats.cost) {
          statsParts.push(`$${stats.cost.toFixed(3)}${usingSubscription ? " est (sub)" : ""}`);
        }
        statsParts.push(`${formatTokens(ctxInfo.contextWindow)} window`);
        if (authStatus?.configured) {
          const source = authStatus.label || authStatus.source || "configured";
          statsParts.push(`auth:${source}${usingOAuth ? "/oauth" : "/api-key"}`);
        }
        const statusLine = statsParts.map((part) => part.includes("\x1b[") ? part : theme.fg("text", part)).join(" ");

        const lines: string[] = [];
        if (visibleWidth(requestedLine) <= width) {
          lines.push(requestedLine);
        } else {
          const compactModel = `${theme.fg("text", "[")}${boldLabel(theme, model?.id || "no-model")} ${theme.fg("accent", "🧠")}${thinkingText(theme, thinking)}${theme.fg("text", "]")}`;
          const compactLine = [
            compactModel,
            `${theme.fg("accent", "📁")} ${theme.fg("text", dir)}`,
            `${theme.fg("accent", "👤")} ${theme.fg("text", acct)}`,
          ].join(theme.fg("muted", " | "));
          lines.push(truncateToWidth(compactLine, width, theme.fg("muted", "…")));
          const contextAndQuota = showCodexQuota
            ? `${boldLabel(theme, "ctx:")}${ctxPct} ${quotaText}`
            : showIbmCredits
              ? `${boldLabel(theme, "ctx:")}${ctxPct} ${formatIbmCredits(theme)}`
              : `${boldLabel(theme, "ctx:")}${ctxPct}`;
          lines.push(truncateToWidth(contextAndQuota, width, theme.fg("muted", "…")));
        }

        lines.push(truncateToWidth(statusLine, width, theme.fg("muted", "…")));

        const extensionStatuses = footerData.getExtensionStatuses();
        if (extensionStatuses.size > 0) {
          const statusText = Array.from(extensionStatuses.entries())
            .sort(([a]: [string, string], [b]: [string, string]) => a.localeCompare(b))
            .map(([, text]: [string, string]) => text.replace(/[\r\n\t]/g, " ").replace(/ +/g, " ").trim())
            .join(" ");
          lines.push(truncateToWidth(theme.fg("text", statusText), width, theme.fg("muted", "…")));
        }

        return lines;
      },
    };
  });
}

function shouldRenderStatusLine(ctx: any): boolean {
  return ctx.mode === "tui" || ctx.mode === "rpc";
}

export default function enhancedStatusLine(pi: ExtensionAPI) {
  pi.registerCommand("status-refresh", {
    description: "Refresh quota or credit data for the active provider",
    handler: async (_args, ctx) => {
      try {
        const isIbm = ctx.model?.provider === "ibm-services-essentials";
        const refreshed = isIbm ? await queryIbmCredits() : await queryCodexQuota(ctx);
        const label = isIbm ? "IBM credit" : "Codex quota";
        ctx.ui.notify(refreshed ? `${label} status refreshed` : `${label} data was unavailable`, refreshed ? "info" : "warning");
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        ctx.ui.notify(`Status refresh failed: ${message}`, "error");
      }
    },
  });

  pi.on("session_start", (_event, ctx) => {
    if (!shouldRenderStatusLine(ctx)) return;
    installFooter(ctx);
    if (ctx.model?.provider === "ibm-services-essentials" && Date.now() - lastIbmBudgetRefreshAt > 5 * 60_000) {
      void queryIbmCredits().catch(() => false);
    }
  });

  pi.on("model_select", (event) => {
    if (event.model.provider === "ibm-services-essentials" && Date.now() - lastIbmBudgetRefreshAt > 5 * 60_000) {
      void queryIbmCredits().catch(() => false);
    }
    requestFooterRender?.();
  });

  pi.on("after_provider_response", (event, ctx) => {
    if (event.status < 200 || event.status >= 300) return;
    if (ctx.model?.provider === "openai-codex") captureOpenAICodexQuota(event.headers ?? {});
    if (ctx.model?.provider === "ibm-services-essentials") captureIbmCredits(event.headers ?? {});
  });
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, resolve, sep, isAbsolute } from "node:path";
import { homedir } from "node:os";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

const AGENT_DIR = process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent");
const AUTH_PATH = join(AGENT_DIR, "auth.json");
const QUOTA_CACHE_PATH = join(AGENT_DIR, "status-line-quota.json");
const IBM_CREDITS_CACHE_PATH = join(AGENT_DIR, "status-line-ibm-credits.json");
const IBM_TEAM_ID = process.env.IBM_SERVICES_ESSENTIALS_TEAM_ID || "6a8d8b68f91e25193bbd853d";
const IBM_BUDGET_URL = `https://servicesessentials.ibm.com/services/integrations/team/${IBM_TEAM_ID}/budget`;
const IBM_API_KEY_HELPER = join(AGENT_DIR, "bin", "ibm-services-essentials-api-key");
const IBM_DEFAULT_MAX_CREDITS = Number(process.env.IBM_SERVICES_ESSENTIALS_MAX_CREDITS || 500);

type QuotaBucket = {
  label: "5h" | "7d";
  percent?: number;
  resetAt?: number;
  resetAfterSeconds?: number;
  family?: string;
  limitName?: string;
};

type QuotaState = {
  updatedAt: number;
  buckets: Partial<Record<"5h" | "7d", QuotaBucket>>;
  families?: Record<string, Partial<Record<"5h" | "7d", QuotaBucket>>>;
  activeLimit?: string;
  planType?: string;
};

type IbmCreditsState = {
  updatedAt: number;
  teamId?: string;
  spendCredits: number;
  maxCredits: number;
  softCredits?: number;
  resetAt?: number;
  blocked?: boolean;
  source: "budget" | "response-header";
};

let quotaState: QuotaState | undefined = loadQuotaCache();
let ibmCreditsState: IbmCreditsState | undefined = loadIbmCreditsCache();
let requestFooterRender: (() => void) | undefined;
let lastIbmBudgetRefreshAt = 0;
let authCache: { mtimeMs: number; value: Record<string, any> } | undefined;

function loadQuotaCache(): QuotaState | undefined {
  try {
    if (!existsSync(QUOTA_CACHE_PATH)) return undefined;
    const parsed = JSON.parse(readFileSync(QUOTA_CACHE_PATH, "utf8"));
    if (!parsed || typeof parsed !== "object") return undefined;
    if (typeof parsed.updatedAt !== "number") return undefined;
    const state = parsed as QuotaState;
    const fiveHour = state.buckets?.["5h"];
    const sevenDay = state.buckets?.["7d"];
    // Older cache versions could combine a model-specific 5h quota with the
    // account-wide 7d quota. Never present percentages from different families
    // as if they form one limit pair.
    if (fiveHour && sevenDay && (fiveHour.family ?? "") !== (sevenDay.family ?? "")) {
      delete state.buckets["5h"];
    }
    return state;
  } catch {
    return undefined;
  }
}

function saveQuotaCache(state: QuotaState): void {
  try {
    writeFileSync(QUOTA_CACHE_PATH, JSON.stringify(state, null, 2) + "\n", { mode: 0o600 });
  } catch {
    // Best-effort cache only; footer should never fail because of this.
  }
}

function loadIbmCreditsCache(): IbmCreditsState | undefined {
  try {
    if (!existsSync(IBM_CREDITS_CACHE_PATH)) return undefined;
    const state = JSON.parse(readFileSync(IBM_CREDITS_CACHE_PATH, "utf8")) as IbmCreditsState;
    if (!Number.isFinite(state.updatedAt) || !Number.isFinite(state.spendCredits) || !Number.isFinite(state.maxCredits)) return undefined;
    return state;
  } catch {
    return undefined;
  }
}

function saveIbmCreditsCache(state: IbmCreditsState): void {
  try {
    writeFileSync(IBM_CREDITS_CACHE_PATH, JSON.stringify(state, null, 2) + "\n", { mode: 0o600 });
  } catch {
    // Best-effort cache only; footer should never fail because of this.
  }
}

function readIbmApiKey(): string | undefined {
  try {
    const key = execFileSync(IBM_API_KEY_HELPER, {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
      timeout: 10_000,
    }).trim();
    return key || undefined;
  } catch {
    return undefined;
  }
}

function storeIbmCredits(state: IbmCreditsState): void {
  ibmCreditsState = state;
  saveIbmCreditsCache(state);
  requestFooterRender?.();
}

async function queryIbmCredits(signal?: AbortSignal): Promise<boolean> {
  const apiKey = readIbmApiKey();
  if (!apiKey) return false;
  lastIbmBudgetRefreshAt = Date.now();

  const response = await fetch(IBM_BUDGET_URL, {
    headers: { "Accept": "application/json", "Authorization": `Bearer ${apiKey}` },
    signal: signal ?? AbortSignal.timeout(15_000),
  });
  if (!response.ok) return false;

  const payload = await response.json() as Record<string, unknown>;
  const spendCredits = coerceNumber(payload.advantageCredits) ?? coerceNumber(payload.spendUsd);
  const maxCredits = coerceNumber(payload.maxAdvantageCredits) ?? coerceNumber(payload.maxBudgetUsd);
  if (spendCredits === undefined || maxCredits === undefined) return false;

  storeIbmCredits({
    updatedAt: Date.now(),
    teamId: typeof payload.teamId === "string" ? payload.teamId : IBM_TEAM_ID,
    spendCredits,
    maxCredits,
    softCredits: coerceNumber(payload.softAdvantageCredits) ?? coerceNumber(payload.softBudgetUsd),
    resetAt: coerceNumber(payload.budgetResetAtEpochSeconds),
    blocked: typeof payload.blocked === "boolean" ? payload.blocked : undefined,
    source: "budget",
  });
  return true;
}

function captureIbmCredits(headersIn: Record<string, string>): boolean {
  const headers: Record<string, string> = {};
  for (const [key, value] of Object.entries(headersIn)) headers[key.toLowerCase()] = value;
  const spendCredits = coerceNumber(headers["x-litellm-key-spend"]);
  if (spendCredits === undefined) return false;

  storeIbmCredits({
    updatedAt: Date.now(),
    teamId: ibmCreditsState?.teamId ?? IBM_TEAM_ID,
    spendCredits,
    maxCredits: ibmCreditsState?.maxCredits ?? IBM_DEFAULT_MAX_CREDITS,
    softCredits: ibmCreditsState?.softCredits,
    resetAt: ibmCreditsState?.resetAt,
    blocked: ibmCreditsState?.blocked,
    source: ibmCreditsState?.source === "budget" ? "budget" : "response-header",
  });
  return true;
}

function formatCwd(cwd: string): string {
  const home = process.env.HOME || process.env.USERPROFILE;
  if (!home) return cwd;
  const resolvedCwd = resolve(cwd);
  const resolvedHome = resolve(home);
  const rel = relative(resolvedHome, resolvedCwd);
  const inside = rel === "" || (rel !== ".." && !rel.startsWith(`..${sep}`) && !isAbsolute(rel));
  return inside ? (rel === "" ? "~" : `~${sep}${rel}`) : cwd;
}

function formatCredits(value: number): string {
  if (!Number.isFinite(value)) return "?";
  if (Math.abs(value) >= 1_000) return value.toLocaleString(undefined, { maximumFractionDigits: 0 });
  return value.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}

function formatIbmCredits(theme: any): string {
  if (!ibmCreditsState) return `${boldLabel(theme, "credits:")}${theme.fg("warning", "pending")}`;
  const available = Math.max(0, ibmCreditsState.maxCredits - ibmCreditsState.spendCredits);
  const ratio = ibmCreditsState.maxCredits > 0 ? available / ibmCreditsState.maxCredits : 0;
  const color = ibmCreditsState.blocked || ratio <= 0.1 ? "error" : ratio <= 0.2 ? "warning" : "success";
  const approximate = ibmCreditsState.source === "response-header" ? "~" : "";
  const reset = ibmCreditsState.resetAt && ibmCreditsState.resetAt * 1000 > Date.now()
    ? ` ${theme.fg("muted", `(resets ${formatWeekdayHHMM(new Date(ibmCreditsState.resetAt * 1000))})`)}`
    : "";
  return `${boldLabel(theme, "credits:")}${theme.fg(color, `${approximate}${formatCredits(available)}/${formatCredits(ibmCreditsState.maxCredits)}`)}${reset}`;
}

function formatTokens(count: number): string {
  if (!Number.isFinite(count) || count <= 0) return "0";
  if (count < 1_000) return String(Math.round(count));
  if (count < 10_000) return `${(count / 1_000).toFixed(1)}k`;
  if (count < 1_000_000) return `${Math.round(count / 1_000)}k`;
  if (count < 10_000_000) return `${(count / 1_000_000).toFixed(1)}M`;
  return `${Math.round(count / 1_000_000)}M`;
}

function colorPercent(theme: any, value: number | undefined, suffix = "%", unknownLabel = `?${suffix}`): string {
  if (value === undefined || !Number.isFinite(value)) return theme.fg("warning", unknownLabel);
  const text = `${Math.max(0, Math.min(999, value)).toFixed(0)}${suffix}`;
  if (value <= 50) return theme.fg("success", text);
  if (value <= 80) return theme.fg("warning", text);
  return theme.fg("error", text);
}

function formatTimeHHMM(date: Date): string {
  return date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit", hour12: false });
}

function formatWeekdayHHMM(date: Date): string {
  return `${date.toLocaleDateString(undefined, { weekday: "short" })} ${formatTimeHHMM(date)}`;
}

function resetDate(bucket: QuotaBucket, observedAt: number): Date | undefined {
  if (bucket.resetAt && Number.isFinite(bucket.resetAt)) return new Date(bucket.resetAt * 1000);
  if (bucket.resetAfterSeconds && Number.isFinite(bucket.resetAfterSeconds)) {
    return new Date(observedAt + bucket.resetAfterSeconds * 1000);
  }
  return undefined;
}

function formatQuotaBucket(theme: any, label: "5h" | "7d", bucket: QuotaBucket | undefined, quotaKnown: boolean): string {
  if (!bucket) {
    return quotaKnown
      ? `${label}:${theme.fg("muted", "n/a")} ${theme.fg("muted", "(not reported)")}`
      : `${label}:${theme.fg("warning", "pending")} ${theme.fg("muted", "(run /status-refresh)")}`;
  }
  const date = resetDate(bucket, quotaState?.updatedAt ?? Date.now());
  const expired = date !== undefined && date.getTime() <= Date.now();
  const pct = colorPercent(theme, expired ? undefined : bucket.percent, "%", "pending");
  const reset = expired
    ? "refresh pending"
    : date
      ? (label === "7d" ? formatWeekdayHHMM(date) : formatTimeHHMM(date))
      : "unknown";
  return `${label}:${pct} ${theme.fg("muted", `(resets ${reset})`)}`;
}

function normalizeLimitName(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]/g, "");
}

function quotaBucketsForModel(modelId: string | undefined): Partial<Record<"5h" | "7d", QuotaBucket>> {
  if (!quotaState) return {};
  const normalizedModel = normalizeLimitName(modelId ?? "");
  if (normalizedModel.includes("spark")) {
    for (const buckets of Object.values(quotaState.families ?? {})) {
      const limitName = buckets["5h"]?.limitName ?? buckets["7d"]?.limitName ?? "";
      const normalizedLimit = normalizeLimitName(limitName);
      if (normalizedLimit && (normalizedModel.includes(normalizedLimit) || normalizedLimit.includes(normalizedModel))) {
        return buckets;
      }
    }
    return {};
  }
  return quotaState.buckets;
}

function coerceNumber(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return undefined;
}

function header(headers: Record<string, string>, name: string): string | undefined {
  return headers[name.toLowerCase()];
}

function captureOpenAICodexQuota(headersIn: Record<string, string>): boolean {
  const headers: Record<string, string> = {};
  for (const [key, value] of Object.entries(headersIn)) headers[key.toLowerCase()] = value;

  type Candidate = QuotaBucket & { family: string; role: "primary" | "secondary" };
  const candidates: Candidate[] = [];

  // Supports both root headers (x-codex-primary-...) and named families such as
  // x-codex-bengalfox-primary-... used by Codex subscription limits.
  for (const [key] of Object.entries(headers)) {
    const match = key.match(/^x-codex(?:-([a-z0-9]+))?-(primary|secondary)-window-minutes$/i);
    if (!match) continue;
    const family = match[1] ?? "";
    const role = match[2] as "primary" | "secondary";
    const prefix = family ? `x-codex-${family}-${role}` : `x-codex-${role}`;
    const minutes = coerceNumber(header(headers, `${prefix}-window-minutes`));
    if (minutes !== 300 && minutes !== 10080) continue;
    candidates.push({
      label: minutes === 300 ? "5h" : "7d",
      family,
      role,
      limitName: family ? header(headers, `x-codex-${family}-limit-name`) : header(headers, "x-codex-active-limit"),
      percent: coerceNumber(header(headers, `${prefix}-used-percent`)),
      resetAt: coerceNumber(header(headers, `${prefix}-reset-at`)),
      resetAfterSeconds: coerceNumber(header(headers, `${prefix}-reset-after-seconds`)),
    });
  }

  // Keep both buckets in the same quota family. Root headers describe the
  // active model/account limit; named families (for example a Spark-specific
  // allowance) must not be mixed into that pair.
  const rootCandidates = candidates.filter((candidate) => candidate.family === "");
  let selected = rootCandidates;
  if (selected.length === 0 && candidates.length > 0) {
    const counts = new Map<string, number>();
    for (const candidate of candidates) counts.set(candidate.family, (counts.get(candidate.family) ?? 0) + 1);
    const family = [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
    selected = candidates.filter((candidate) => candidate.family === family);
  }

  const families: Record<string, Partial<Record<"5h" | "7d", QuotaBucket>>> = {};
  for (const candidate of candidates) {
    if (!candidate.family) continue;
    (families[candidate.family] ??= {})[candidate.label] = candidate;
  }

  const next: QuotaState = {
    updatedAt: Date.now(),
    buckets: {
      "5h": selected.find((candidate) => candidate.label === "5h"),
      "7d": selected.find((candidate) => candidate.label === "7d"),
    },
    families,
    activeLimit: header(headers, "x-codex-active-limit"),
    planType: header(headers, "x-codex-plan-type"),
  };

  if (next.buckets["5h"] || next.buckets["7d"]) {
    quotaState = next;
    saveQuotaCache(next);
    requestFooterRender?.();
    return true;
  }
  return false;
}

async function queryCodexQuota(ctx: any): Promise<boolean> {
  const auth = await ctx.modelRegistry?.getProviderAuth?.("openai-codex");
  const token = auth?.auth?.apiKey;
  if (!token || typeof token !== "string") return false;

  const claims = decodeJwtPayload(token);
  const accountId = claims?.["https://api.openai.com/auth"]?.chatgpt_account_id;
  if (!accountId) return false;

  const response = await fetch("https://chatgpt.com/backend-api/codex/responses", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${token}`,
      "chatgpt-account-id": String(accountId),
      "originator": "pi",
      "User-Agent": "pi-coding-agent",
      "OpenAI-Beta": "responses=experimental",
      "accept": "text/event-stream",
      "content-type": "application/json",
    },
    body: JSON.stringify({
      model: ctx.model?.provider === "openai-codex" ? ctx.model.id : "gpt-5.4-mini",
      store: false,
      stream: true,
      instructions: "Return the single word ok.",
      input: [{ role: "user", content: [{ type: "input_text", text: "ok" }] }],
      text: { verbosity: "low" },
    }),
    signal: AbortSignal.timeout(15_000),
  });

  const headers: Record<string, string> = {};
  response.headers.forEach((value, key) => {
    headers[key] = value;
  });
  const captured = response.ok && captureOpenAICodexQuota(headers);
  await response.body?.cancel().catch(() => undefined);
  return captured;
}

function decodeJwtPayload(token: string): Record<string, any> | undefined {
  const parts = token.split(".");
  if (parts.length < 2 || !parts[1]) return undefined;
  try {
    const base64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, "=");
    return JSON.parse(Buffer.from(padded, "base64").toString("utf8"));
  } catch {
    return undefined;
  }
}

function readAuthJson(): Record<string, any> {
  try {
    if (!existsSync(AUTH_PATH)) return {};
    const mtimeMs = statSync(AUTH_PATH).mtimeMs;
    if (authCache?.mtimeMs === mtimeMs) return authCache.value;
    const value = JSON.parse(readFileSync(AUTH_PATH, "utf8"));
    authCache = { mtimeMs, value };
    return value;
  } catch {
    return {};
  }
}

function accountLabel(provider: string | undefined, ctx: any): string {
  if (!provider) return "unknown";
  if (provider === "ibm-services-essentials") return `IBM:${process.env.ICA_OP_KEY_NAME || "ICA_CODEX"}`;

  const auth = readAuthJson()[provider];
  if (auth?.type === "oauth") {
    const claims = typeof auth.access === "string" ? decodeJwtPayload(auth.access) : undefined;
    const openaiAuth = claims?.["https://api.openai.com/auth"];
    const profile = claims?.["https://api.openai.com/profile"];
    if (profile?.email) return String(profile.email);
    if (profile?.name) return String(profile.name);
    if (openaiAuth?.chatgpt_account_id) return `acct:${String(openaiAuth.chatgpt_account_id).slice(0, 8)}`;
    if (auth.accountId) return `acct:${String(auth.accountId).slice(0, 8)}`;
    return `${provider}:oauth`;
  }

  const status = ctx.modelRegistry?.getProviderAuthStatus?.(provider);
  if (status?.configured) return status.label || status.source || "configured";
  return provider;
}

function contextPercent(ctx: any): { percent?: number; contextWindow: number } {
  const usage = ctx.getContextUsage?.();
  return {
    percent: usage?.percent ?? undefined,
    contextWindow: usage?.contextWindow ?? ctx.model?.contextWindow ?? 0,
  };
}

function usageStats(ctx: any) {
  const totals = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, latestCacheHitRate: undefined as number | undefined };
  for (const entry of ctx.sessionManager.getEntries()) {
    const msg = entry.type === "message" ? entry.message : undefined;
    const usage = msg?.role === "assistant" || msg?.role === "toolResult" ? msg.usage : entry.usage;
    if (!usage) continue;
    totals.input += usage.input ?? 0;
    totals.output += usage.output ?? 0;
    totals.cacheRead += usage.cacheRead ?? 0;
    totals.cacheWrite += usage.cacheWrite ?? 0;
    totals.cost += usage.cost?.total ?? 0;
    if (msg?.role === "assistant") {
      const prompt = (usage.input ?? 0) + (usage.cacheRead ?? 0) + (usage.cacheWrite ?? 0);
      totals.latestCacheHitRate = prompt > 0 ? ((usage.cacheRead ?? 0) / prompt) * 100 : undefined;
    }
  }
  return totals;
}

function boldLabel(theme: any, text: string): string {
  return theme.bold(theme.fg("accent", text));
}

function thinkingText(theme: any, level: string): string {
  const colorByLevel: Record<string, string> = {
    off: "muted",
    minimal: "thinkingMinimal",
    low: "thinkingLow",
    medium: "thinkingMedium",
    high: "thinkingHigh",
    xhigh: "thinkingXhigh",
    max: "thinkingXhigh",
  };
  const color = colorByLevel[level] || "accent";
  try {
    return theme.bold(theme.fg(color, level));
  } catch {
    return theme.bold(theme.fg("accent", level));
  }
}

function installFooter(ctx: any): void {
  ctx.ui.setFooter((tui: any, theme: any, footerData: any) => {
    requestFooterRender = () => tui.requestRender();
    const unsubscribeBranch = footerData.onBranchChange(() => tui.requestRender());

    return {
      dispose() {
        unsubscribeBranch?.();
        if (requestFooterRender) requestFooterRender = undefined;
      },
      invalidate() {},
      render(width: number): string[] {
        const model = ctx.model;
        const modelText = model ? `${model.provider}/${model.id}` : "no-model";
        const thinking = ctx.thinkingLevel || (model?.reasoning ? "off" : "off");

        let dir = formatCwd(ctx.sessionManager.getCwd());
        const branch = footerData.getGitBranch();
        if (branch) dir += ` (${branch})`;
        const sessionName = ctx.sessionManager.getSessionName?.();
        if (sessionName) dir += ` • ${sessionName}`;

        const acct = accountLabel(model?.provider, ctx);
        const ctxInfo = contextPercent(ctx);
        const ctxPct = colorPercent(theme, ctxInfo.percent, "%", "pending");
        const showCodexQuota = model?.provider === "openai-codex";
        const showIbmCredits = model?.provider === "ibm-services-essentials";
        const quota = quotaBucketsForModel(model?.id);
        const quotaKnown = quotaState !== undefined && (!normalizeLimitName(model?.id ?? "").includes("spark") || Object.keys(quota).length > 0);
        const quotaText = `${theme.fg("text", "{")}${formatQuotaBucket(theme, "5h", quota["5h"], quotaKnown)} ${formatQuotaBucket(theme, "7d", quota["7d"], quotaKnown)}${theme.fg("text", "}")}`;

        const requestedParts = [
          `${theme.fg("text", "[")}${boldLabel(theme, modelText)} ${theme.fg("accent", "🧠")}${thinkingText(theme, thinking)}${theme.fg("text", "]")}`,
          `${theme.fg("accent", "📁")} ${theme.fg("text", dir)}`,
          `${theme.fg("accent", "👤")} ${theme.fg("text", acct)}`,
          `${boldLabel(theme, "ctx:")}${ctxPct}`,
        ];
        if (showCodexQuota) requestedParts.push(quotaText);
        if (showIbmCredits) requestedParts.push(formatIbmCredits(theme));
        const requestedLine = requestedParts.join(theme.fg("muted", " | "));

        const stats = usageStats(ctx);
        const statsParts = [
          `${boldLabel(theme, "tokens")}`,
          `↑${formatTokens(stats.input)}`,
          `↓${formatTokens(stats.output)}`,
        ];
        if (stats.cacheRead) statsParts.push(`R${formatTokens(stats.cacheRead)}`);
        if (stats.cacheWrite) statsParts.push(`W${formatTokens(stats.cacheWrite)}`);
        if ((stats.cacheRead || stats.cacheWrite) && stats.latestCacheHitRate !== undefined) {
          statsParts.push(`CH${colorPercent(theme, stats.latestCacheHitRate)}`);
        }
        const authStatus = model ? ctx.modelRegistry?.getProviderAuthStatus?.(model.provider) : undefined;
        const usingOAuth = model ? ctx.modelRegistry?.isUsingOAuth?.(model) === true : false;
        const provider = model ? ctx.modelRegistry?.getProvider?.(model.provider) : undefined;
        const usingSubscription = usingOAuth && provider?.auth?.oauth?.isSubscription === true;
        if (stats.cost) {
          statsParts.push(`$${stats.cost.toFixed(3)}${usingSubscription ? " est (sub)" : ""}`);
        }
        statsParts.push(`${formatTokens(ctxInfo.contextWindow)} window`);
        if (authStatus?.configured) {
          const source = authStatus.label || authStatus.source || "configured";
          statsParts.push(`auth:${source}${usingOAuth ? "/oauth" : "/api-key"}`);
        }
        const statusLine = statsParts.map((part) => part.includes("\x1b[") ? part : theme.fg("text", part)).join(" ");

        const lines: string[] = [];
        if (visibleWidth(requestedLine) <= width) {
          lines.push(requestedLine);
        } else {
          const compactModel = `${theme.fg("text", "[")}${boldLabel(theme, model?.id || "no-model")} ${theme.fg("accent", "🧠")}${thinkingText(theme, thinking)}${theme.fg("text", "]")}`;
          const compactLine = [
            compactModel,
            `${theme.fg("accent", "📁")} ${theme.fg("text", dir)}`,
            `${theme.fg("accent", "👤")} ${theme.fg("text", acct)}`,
          ].join(theme.fg("muted", " | "));
          lines.push(truncateToWidth(compactLine, width, theme.fg("muted", "…")));
          const contextAndQuota = showCodexQuota
            ? `${boldLabel(theme, "ctx:")}${ctxPct} ${quotaText}`
            : showIbmCredits
              ? `${boldLabel(theme, "ctx:")}${ctxPct} ${formatIbmCredits(theme)}`
              : `${boldLabel(theme, "ctx:")}${ctxPct}`;
          lines.push(truncateToWidth(contextAndQuota, width, theme.fg("muted", "…")));
        }

        lines.push(truncateToWidth(statusLine, width, theme.fg("muted", "…")));

        const extensionStatuses = footerData.getExtensionStatuses();
        if (extensionStatuses.size > 0) {
          const statusText = Array.from(extensionStatuses.entries())
            .sort(([a]: [string, string], [b]: [string, string]) => a.localeCompare(b))
            .map(([, text]: [string, string]) => text.replace(/[\r\n\t]/g, " ").replace(/ +/g, " ").trim())
            .join(" ");
          lines.push(truncateToWidth(theme.fg("text", statusText), width, theme.fg("muted", "…")));
        }

        return lines;
      },
    };
  });
}

function shouldRenderStatusLine(ctx: any): boolean {
  return ctx.mode === "tui" || ctx.mode === "rpc";
}

export default function enhancedStatusLine(pi: ExtensionAPI) {
  pi.registerCommand("status-refresh", {
    description: "Refresh quota or credit data for the active provider",
    handler: async (_args, ctx) => {
      try {
        const isIbm = ctx.model?.provider === "ibm-services-essentials";
        const refreshed = isIbm ? await queryIbmCredits() : await queryCodexQuota(ctx);
        const label = isIbm ? "IBM credit" : "Codex quota";
        ctx.ui.notify(refreshed ? `${label} status refreshed` : `${label} data was unavailable`, refreshed ? "info" : "warning");
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        ctx.ui.notify(`Status refresh failed: ${message}`, "error");
      }
    },
  });

  pi.on("session_start", (_event, ctx) => {
    if (!shouldRenderStatusLine(ctx)) return;
    installFooter(ctx);
    if (ctx.model?.provider === "ibm-services-essentials" && Date.now() - lastIbmBudgetRefreshAt > 5 * 60_000) {
      void queryIbmCredits().catch(() => false);
    }
  });

  pi.on("model_select", (event) => {
    if (event.model.provider === "ibm-services-essentials" && Date.now() - lastIbmBudgetRefreshAt > 5 * 60_000) {
      void queryIbmCredits().catch(() => false);
    }
    requestFooterRender?.();
  });

  pi.on("after_provider_response", (event, ctx) => {
    if (event.status < 200 || event.status >= 300) return;
    if (ctx.model?.provider === "openai-codex") captureOpenAICodexQuota(event.headers ?? {});
    if (ctx.model?.provider === "ibm-services-essentials") captureIbmCredits(event.headers ?? {});
  });
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, resolve, sep, isAbsolute } from "node:path";
import { homedir } from "node:os";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

const AGENT_DIR = process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent");
const AUTH_PATH = join(AGENT_DIR, "auth.json");
const QUOTA_CACHE_PATH = join(AGENT_DIR, "status-line-quota.json");
const IBM_CREDITS_CACHE_PATH = join(AGENT_DIR, "status-line-ibm-credits.json");
const IBM_TEAM_ID = process.env.IBM_SERVICES_ESSENTIALS_TEAM_ID || "6a8d8b68f91e25193bbd853d";
const IBM_BUDGET_URL = `https://servicesessentials.ibm.com/services/integrations/team/${IBM_TEAM_ID}/budget`;
const IBM_API_KEY_HELPER = join(AGENT_DIR, "bin", "ibm-services-essentials-api-key");
const IBM_DEFAULT_MAX_CREDITS = Number(process.env.IBM_SERVICES_ESSENTIALS_MAX_CREDITS || 500);

type QuotaBucket = {
  label: "5h" | "7d";
  percent?: number;
  resetAt?: number;
  resetAfterSeconds?: number;
  family?: string;
  limitName?: string;
};

type QuotaState = {
  updatedAt: number;
  buckets: Partial<Record<"5h" | "7d", QuotaBucket>>;
  families?: Record<string, Partial<Record<"5h" | "7d", QuotaBucket>>>;
  activeLimit?: string;
  planType?: string;
};

type IbmCreditsState = {
  updatedAt: number;
  teamId?: string;
  spendCredits: number;
  maxCredits: number;
  softCredits?: number;
  resetAt?: number;
  blocked?: boolean;
  source: "budget" | "response-header";
};

let quotaState: QuotaState | undefined = loadQuotaCache();
let ibmCreditsState: IbmCreditsState | undefined = loadIbmCreditsCache();
let requestFooterRender: (() => void) | undefined;
let lastIbmBudgetRefreshAt = 0;
let authCache: { mtimeMs: number; value: Record<string, any> } | undefined;

function loadQuotaCache(): QuotaState | undefined {
  try {
    if (!existsSync(QUOTA_CACHE_PATH)) return undefined;
    const parsed = JSON.parse(readFileSync(QUOTA_CACHE_PATH, "utf8"));
    if (!parsed || typeof parsed !== "object") return undefined;
    if (typeof parsed.updatedAt !== "number") return undefined;
    const state = parsed as QuotaState;
    const fiveHour = state.buckets?.["5h"];
    const sevenDay = state.buckets?.["7d"];
    // Older cache versions could combine a model-specific 5h quota with the
    // account-wide 7d quota. Never present percentages from different families
    // as if they form one limit pair.
    if (fiveHour && sevenDay && (fiveHour.family ?? "") !== (sevenDay.family ?? "")) {
      delete state.buckets["5h"];
    }
    return state;
  } catch {
    return undefined;
  }
}

function saveQuotaCache(state: QuotaState): void {
  try {
    writeFileSync(QUOTA_CACHE_PATH, JSON.stringify(state, null, 2) + "\n", { mode: 0o600 });
  } catch {
    // Best-effort cache only; footer should never fail because of this.
  }
}

function loadIbmCreditsCache(): IbmCreditsState | undefined {
  try {
    if (!existsSync(IBM_CREDITS_CACHE_PATH)) return undefined;
    const state = JSON.parse(readFileSync(IBM_CREDITS_CACHE_PATH, "utf8")) as IbmCreditsState;
    if (!Number.isFinite(state.updatedAt) || !Number.isFinite(state.spendCredits) || !Number.isFinite(state.maxCredits)) return undefined;
    return state;
  } catch {
    return undefined;
  }
}

function saveIbmCreditsCache(state: IbmCreditsState): void {
  try {
    writeFileSync(IBM_CREDITS_CACHE_PATH, JSON.stringify(state, null, 2) + "\n", { mode: 0o600 });
  } catch {
    // Best-effort cache only; footer should never fail because of this.
  }
}

function readIbmApiKey(): string | undefined {
  try {
    const key = execFileSync(IBM_API_KEY_HELPER, {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
      timeout: 10_000,
    }).trim();
    return key || undefined;
  } catch {
    return undefined;
  }
}

function storeIbmCredits(state: IbmCreditsState): void {
  ibmCreditsState = state;
  saveIbmCreditsCache(state);
  requestFooterRender?.();
}

async function queryIbmCredits(signal?: AbortSignal): Promise<boolean> {
  const apiKey = readIbmApiKey();
  if (!apiKey) return false;
  lastIbmBudgetRefreshAt = Date.now();

  const response = await fetch(IBM_BUDGET_URL, {
    headers: { "Accept": "application/json", "Authorization": `Bearer ${apiKey}` },
    signal: signal ?? AbortSignal.timeout(15_000),
  });
  if (!response.ok) return false;

  const payload = await response.json() as Record<string, unknown>;
  const spendCredits = coerceNumber(payload.advantageCredits) ?? coerceNumber(payload.spendUsd);
  const maxCredits = coerceNumber(payload.maxAdvantageCredits) ?? coerceNumber(payload.maxBudgetUsd);
  if (spendCredits === undefined || maxCredits === undefined) return false;

  storeIbmCredits({
    updatedAt: Date.now(),
    teamId: typeof payload.teamId === "string" ? payload.teamId : IBM_TEAM_ID,
    spendCredits,
    maxCredits,
    softCredits: coerceNumber(payload.softAdvantageCredits) ?? coerceNumber(payload.softBudgetUsd),
    resetAt: coerceNumber(payload.budgetResetAtEpochSeconds),
    blocked: typeof payload.blocked === "boolean" ? payload.blocked : undefined,
    source: "budget",
  });
  return true;
}

function captureIbmCredits(headersIn: Record<string, string>): boolean {
  const headers: Record<string, string> = {};
  for (const [key, value] of Object.entries(headersIn)) headers[key.toLowerCase()] = value;
  const spendCredits = coerceNumber(headers["x-litellm-key-spend"]);
  if (spendCredits === undefined) return false;

  storeIbmCredits({
    updatedAt: Date.now(),
    teamId: ibmCreditsState?.teamId ?? IBM_TEAM_ID,
    spendCredits,
    maxCredits: ibmCreditsState?.maxCredits ?? IBM_DEFAULT_MAX_CREDITS,
    softCredits: ibmCreditsState?.softCredits,
    resetAt: ibmCreditsState?.resetAt,
    blocked: ibmCreditsState?.blocked,
    source: ibmCreditsState?.source === "budget" ? "budget" : "response-header",
  });
  return true;
}

function formatCwd(cwd: string): string {
  const home = process.env.HOME || process.env.USERPROFILE;
  if (!home) return cwd;
  const resolvedCwd = resolve(cwd);
  const resolvedHome = resolve(home);
  const rel = relative(resolvedHome, resolvedCwd);
  const inside = rel === "" || (rel !== ".." && !rel.startsWith(`..${sep}`) && !isAbsolute(rel));
  return inside ? (rel === "" ? "~" : `~${sep}${rel}`) : cwd;
}

function formatCredits(value: number): string {
  if (!Number.isFinite(value)) return "?";
  if (Math.abs(value) >= 1_000) return value.toLocaleString(undefined, { maximumFractionDigits: 0 });
  return value.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}

function formatIbmCredits(theme: any): string {
  if (!ibmCreditsState) return `${boldLabel(theme, "credits:")}${theme.fg("warning", "pending")}`;
  const available = Math.max(0, ibmCreditsState.maxCredits - ibmCreditsState.spendCredits);
  const ratio = ibmCreditsState.maxCredits > 0 ? available / ibmCreditsState.maxCredits : 0;
  const color = ibmCreditsState.blocked || ratio <= 0.1 ? "error" : ratio <= 0.2 ? "warning" : "success";
  const approximate = ibmCreditsState.source === "response-header" ? "~" : "";
  const reset = ibmCreditsState.resetAt && ibmCreditsState.resetAt * 1000 > Date.now()
    ? ` ${theme.fg("muted", `(resets ${formatWeekdayHHMM(new Date(ibmCreditsState.resetAt * 1000))})`)}`
    : "";
  return `${boldLabel(theme, "credits:")}${theme.fg(color, `${approximate}${formatCredits(available)}/${formatCredits(ibmCreditsState.maxCredits)}`)}${reset}`;
}

function formatTokens(count: number): string {
  if (!Number.isFinite(count) || count <= 0) return "0";
  if (count < 1_000) return String(Math.round(count));
  if (count < 10_000) return `${(count / 1_000).toFixed(1)}k`;
  if (count < 1_000_000) return `${Math.round(count / 1_000)}k`;
  if (count < 10_000_000) return `${(count / 1_000_000).toFixed(1)}M`;
  return `${Math.round(count / 1_000_000)}M`;
}

function colorPercent(theme: any, value: number | undefined, suffix = "%", unknownLabel = `?${suffix}`): string {
  if (value === undefined || !Number.isFinite(value)) return theme.fg("warning", unknownLabel);
  const text = `${Math.max(0, Math.min(999, value)).toFixed(0)}${suffix}`;
  if (value <= 50) return theme.fg("success", text);
  if (value <= 80) return theme.fg("warning", text);
  return theme.fg("error", text);
}

function formatTimeHHMM(date: Date): string {
  return date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit", hour12: false });
}

function formatWeekdayHHMM(date: Date): string {
  return `${date.toLocaleDateString(undefined, { weekday: "short" })} ${formatTimeHHMM(date)}`;
}

function resetDate(bucket: QuotaBucket, observedAt: number): Date | undefined {
  if (bucket.resetAt && Number.isFinite(bucket.resetAt)) return new Date(bucket.resetAt * 1000);
  if (bucket.resetAfterSeconds && Number.isFinite(bucket.resetAfterSeconds)) {
    return new Date(observedAt + bucket.resetAfterSeconds * 1000);
  }
  return undefined;
}

function formatQuotaBucket(theme: any, label: "5h" | "7d", bucket: QuotaBucket | undefined, quotaKnown: boolean): string {
  if (!bucket) {
    return quotaKnown
      ? `${label}:${theme.fg("muted", "n/a")} ${theme.fg("muted", "(not reported)")}`
      : `${label}:${theme.fg("warning", "pending")} ${theme.fg("muted", "(run /status-refresh)")}`;
  }
  const date = resetDate(bucket, quotaState?.updatedAt ?? Date.now());
  const expired = date !== undefined && date.getTime() <= Date.now();
  const pct = colorPercent(theme, expired ? undefined : bucket.percent, "%", "pending");
  const reset = expired
    ? "refresh pending"
    : date
      ? (label === "7d" ? formatWeekdayHHMM(date) : formatTimeHHMM(date))
      : "unknown";
  return `${label}:${pct} ${theme.fg("muted", `(resets ${reset})`)}`;
}

function normalizeLimitName(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]/g, "");
}

function quotaBucketsForModel(modelId: string | undefined): Partial<Record<"5h" | "7d", QuotaBucket>> {
  if (!quotaState) return {};
  const normalizedModel = normalizeLimitName(modelId ?? "");
  if (normalizedModel.includes("spark")) {
    for (const buckets of Object.values(quotaState.families ?? {})) {
      const limitName = buckets["5h"]?.limitName ?? buckets["7d"]?.limitName ?? "";
      const normalizedLimit = normalizeLimitName(limitName);
      if (normalizedLimit && (normalizedModel.includes(normalizedLimit) || normalizedLimit.includes(normalizedModel))) {
        return buckets;
      }
    }
    return {};
  }
  return quotaState.buckets;
}

function coerceNumber(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return undefined;
}

function header(headers: Record<string, string>, name: string): string | undefined {
  return headers[name.toLowerCase()];
}

function captureOpenAICodexQuota(headersIn: Record<string, string>): boolean {
  const headers: Record<string, string> = {};
  for (const [key, value] of Object.entries(headersIn)) headers[key.toLowerCase()] = value;

  type Candidate = QuotaBucket & { family: string; role: "primary" | "secondary" };
  const candidates: Candidate[] = [];

  // Supports both root headers (x-codex-primary-...) and named families such as
  // x-codex-bengalfox-primary-... used by Codex subscription limits.
  for (const [key] of Object.entries(headers)) {
    const match = key.match(/^x-codex(?:-([a-z0-9]+))?-(primary|secondary)-window-minutes$/i);
    if (!match) continue;
    const family = match[1] ?? "";
    const role = match[2] as "primary" | "secondary";
    const prefix = family ? `x-codex-${family}-${role}` : `x-codex-${role}`;
    const minutes = coerceNumber(header(headers, `${prefix}-window-minutes`));
    if (minutes !== 300 && minutes !== 10080) continue;
    candidates.push({
      label: minutes === 300 ? "5h" : "7d",
      family,
      role,
      limitName: family ? header(headers, `x-codex-${family}-limit-name`) : header(headers, "x-codex-active-limit"),
      percent: coerceNumber(header(headers, `${prefix}-used-percent`)),
      resetAt: coerceNumber(header(headers, `${prefix}-reset-at`)),
      resetAfterSeconds: coerceNumber(header(headers, `${prefix}-reset-after-seconds`)),
    });
  }

  // Keep both buckets in the same quota family. Root headers describe the
  // active model/account limit; named families (for example a Spark-specific
  // allowance) must not be mixed into that pair.
  const rootCandidates = candidates.filter((candidate) => candidate.family === "");
  let selected = rootCandidates;
  if (selected.length === 0 && candidates.length > 0) {
    const counts = new Map<string, number>();
    for (const candidate of candidates) counts.set(candidate.family, (counts.get(candidate.family) ?? 0) + 1);
    const family = [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
    selected = candidates.filter((candidate) => candidate.family === family);
  }

  const families: Record<string, Partial<Record<"5h" | "7d", QuotaBucket>>> = {};
  for (const candidate of candidates) {
    if (!candidate.family) continue;
    (families[candidate.family] ??= {})[candidate.label] = candidate;
  }

  const next: QuotaState = {
    updatedAt: Date.now(),
    buckets: {
      "5h": selected.find((candidate) => candidate.label === "5h"),
      "7d": selected.find((candidate) => candidate.label === "7d"),
    },
    families,
    activeLimit: header(headers, "x-codex-active-limit"),
    planType: header(headers, "x-codex-plan-type"),
  };

  if (next.buckets["5h"] || next.buckets["7d"]) {
    quotaState = next;
    saveQuotaCache(next);
    requestFooterRender?.();
    return true;
  }
  return false;
}

async function queryCodexQuota(ctx: any): Promise<boolean> {
  const auth = await ctx.modelRegistry?.getProviderAuth?.("openai-codex");
  const token = auth?.auth?.apiKey;
  if (!token || typeof token !== "string") return false;

  const claims = decodeJwtPayload(token);
  const accountId = claims?.["https://api.openai.com/auth"]?.chatgpt_account_id;
  if (!accountId) return false;

  const response = await fetch("https://chatgpt.com/backend-api/codex/responses", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${token}`,
      "chatgpt-account-id": String(accountId),
      "originator": "pi",
      "User-Agent": "pi-coding-agent",
      "OpenAI-Beta": "responses=experimental",
      "accept": "text/event-stream",
      "content-type": "application/json",
    },
    body: JSON.stringify({
      model: ctx.model?.provider === "openai-codex" ? ctx.model.id : "gpt-5.4-mini",
      store: false,
      stream: true,
      instructions: "Return the single word ok.",
      input: [{ role: "user", content: [{ type: "input_text", text: "ok" }] }],
      text: { verbosity: "low" },
    }),
    signal: AbortSignal.timeout(15_000),
  });

  const headers: Record<string, string> = {};
  response.headers.forEach((value, key) => {
    headers[key] = value;
  });
  const captured = response.ok && captureOpenAICodexQuota(headers);
  await response.body?.cancel().catch(() => undefined);
  return captured;
}

function decodeJwtPayload(token: string): Record<string, any> | undefined {
  const parts = token.split(".");
  if (parts.length < 2 || !parts[1]) return undefined;
  try {
    const base64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, "=");
    return JSON.parse(Buffer.from(padded, "base64").toString("utf8"));
  } catch {
    return undefined;
  }
}

function readAuthJson(): Record<string, any> {
  try {
    if (!existsSync(AUTH_PATH)) return {};
    const mtimeMs = statSync(AUTH_PATH).mtimeMs;
    if (authCache?.mtimeMs === mtimeMs) return authCache.value;
    const value = JSON.parse(readFileSync(AUTH_PATH, "utf8"));
    authCache = { mtimeMs, value };
    return value;
  } catch {
    return {};
  }
}

function accountLabel(provider: string | undefined, ctx: any): string {
  if (!provider) return "unknown";
  if (provider === "ibm-services-essentials") return `IBM:${process.env.ICA_OP_KEY_NAME || "ICA_CODEX"}`;

  const auth = readAuthJson()[provider];
  if (auth?.type === "oauth") {
    const claims = typeof auth.access === "string" ? decodeJwtPayload(auth.access) : undefined;
    const openaiAuth = claims?.["https://api.openai.com/auth"];
    const profile = claims?.["https://api.openai.com/profile"];
    if (profile?.email) return String(profile.email);
    if (profile?.name) return String(profile.name);
    if (openaiAuth?.chatgpt_account_id) return `acct:${String(openaiAuth.chatgpt_account_id).slice(0, 8)}`;
    if (auth.accountId) return `acct:${String(auth.accountId).slice(0, 8)}`;
    return `${provider}:oauth`;
  }

  const status = ctx.modelRegistry?.getProviderAuthStatus?.(provider);
  if (status?.configured) return status.label || status.source || "configured";
  return provider;
}

function contextPercent(ctx: any): { percent?: number; contextWindow: number } {
  const usage = ctx.getContextUsage?.();
  return {
    percent: usage?.percent ?? undefined,
    contextWindow: usage?.contextWindow ?? ctx.model?.contextWindow ?? 0,
  };
}

function usageStats(ctx: any) {
  const totals = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, latestCacheHitRate: undefined as number | undefined };
  for (const entry of ctx.sessionManager.getEntries()) {
    const msg = entry.type === "message" ? entry.message : undefined;
    const usage = msg?.role === "assistant" || msg?.role === "toolResult" ? msg.usage : entry.usage;
    if (!usage) continue;
    totals.input += usage.input ?? 0;
    totals.output += usage.output ?? 0;
    totals.cacheRead += usage.cacheRead ?? 0;
    totals.cacheWrite += usage.cacheWrite ?? 0;
    totals.cost += usage.cost?.total ?? 0;
    if (msg?.role === "assistant") {
      const prompt = (usage.input ?? 0) + (usage.cacheRead ?? 0) + (usage.cacheWrite ?? 0);
      totals.latestCacheHitRate = prompt > 0 ? ((usage.cacheRead ?? 0) / prompt) * 100 : undefined;
    }
  }
  return totals;
}

function boldLabel(theme: any, text: string): string {
  return theme.bold(theme.fg("accent", text));
}

function thinkingText(theme: any, level: string): string {
  const colorByLevel: Record<string, string> = {
    off: "muted",
    minimal: "thinkingMinimal",
    low: "thinkingLow",
    medium: "thinkingMedium",
    high: "thinkingHigh",
    xhigh: "thinkingXhigh",
    max: "thinkingXhigh",
  };
  const color = colorByLevel[level] || "accent";
  try {
    return theme.bold(theme.fg(color, level));
  } catch {
    return theme.bold(theme.fg("accent", level));
  }
}

function installFooter(ctx: any): void {
  ctx.ui.setFooter((tui: any, theme: any, footerData: any) => {
    requestFooterRender = () => tui.requestRender();
    const unsubscribeBranch = footerData.onBranchChange(() => tui.requestRender());

    return {
      dispose() {
        unsubscribeBranch?.();
        if (requestFooterRender) requestFooterRender = undefined;
      },
      invalidate() {},
      render(width: number): string[] {
        const model = ctx.model;
        const modelText = model ? `${model.provider}/${model.id}` : "no-model";
        const thinking = ctx.thinkingLevel || (model?.reasoning ? "off" : "off");

        let dir = formatCwd(ctx.sessionManager.getCwd());
        const branch = footerData.getGitBranch();
        if (branch) dir += ` (${branch})`;
        const sessionName = ctx.sessionManager.getSessionName?.();
        if (sessionName) dir += ` • ${sessionName}`;

        const acct = accountLabel(model?.provider, ctx);
        const ctxInfo = contextPercent(ctx);
        const ctxPct = colorPercent(theme, ctxInfo.percent, "%", "pending");
        const showCodexQuota = model?.provider === "openai-codex";
        const showIbmCredits = model?.provider === "ibm-services-essentials";
        const quota = quotaBucketsForModel(model?.id);
        const quotaKnown = quotaState !== undefined && (!normalizeLimitName(model?.id ?? "").includes("spark") || Object.keys(quota).length > 0);
        const quotaText = `${theme.fg("text", "{")}${formatQuotaBucket(theme, "5h", quota["5h"], quotaKnown)} ${formatQuotaBucket(theme, "7d", quota["7d"], quotaKnown)}${theme.fg("text", "}")}`;

        const requestedParts = [
          `${theme.fg("text", "[")}${boldLabel(theme, modelText)} ${theme.fg("accent", "🧠")}${thinkingText(theme, thinking)}${theme.fg("text", "]")}`,
          `${theme.fg("accent", "📁")} ${theme.fg("text", dir)}`,
          `${theme.fg("accent", "👤")} ${theme.fg("text", acct)}`,
          `${boldLabel(theme, "ctx:")}${ctxPct}`,
        ];
        if (showCodexQuota) requestedParts.push(quotaText);
        if (showIbmCredits) requestedParts.push(formatIbmCredits(theme));
        const requestedLine = requestedParts.join(theme.fg("muted", " | "));

        const stats = usageStats(ctx);
        const statsParts = [
          `${boldLabel(theme, "tokens")}`,
          `↑${formatTokens(stats.input)}`,
          `↓${formatTokens(stats.output)}`,
        ];
        if (stats.cacheRead) statsParts.push(`R${formatTokens(stats.cacheRead)}`);
        if (stats.cacheWrite) statsParts.push(`W${formatTokens(stats.cacheWrite)}`);
        if ((stats.cacheRead || stats.cacheWrite) && stats.latestCacheHitRate !== undefined) {
          statsParts.push(`CH${colorPercent(theme, stats.latestCacheHitRate)}`);
        }
        const authStatus = model ? ctx.modelRegistry?.getProviderAuthStatus?.(model.provider) : undefined;
        const usingOAuth = model ? ctx.modelRegistry?.isUsingOAuth?.(model) === true : false;
        const provider = model ? ctx.modelRegistry?.getProvider?.(model.provider) : undefined;
        const usingSubscription = usingOAuth && provider?.auth?.oauth?.isSubscription === true;
        if (stats.cost) {
          statsParts.push(`$${stats.cost.toFixed(3)}${usingSubscription ? " est (sub)" : ""}`);
        }
        statsParts.push(`${formatTokens(ctxInfo.contextWindow)} window`);
        if (authStatus?.configured) {
          const source = authStatus.label || authStatus.source || "configured";
          statsParts.push(`auth:${source}${usingOAuth ? "/oauth" : "/api-key"}`);
        }
        const statusLine = statsParts.map((part) => part.includes("\x1b[") ? part : theme.fg("text", part)).join(" ");

        const lines: string[] = [];
        if (visibleWidth(requestedLine) <= width) {
          lines.push(requestedLine);
        } else {
          const compactModel = `${theme.fg("text", "[")}${boldLabel(theme, model?.id || "no-model")} ${theme.fg("accent", "🧠")}${thinkingText(theme, thinking)}${theme.fg("text", "]")}`;
          const compactLine = [
            compactModel,
            `${theme.fg("accent", "📁")} ${theme.fg("text", dir)}`,
            `${theme.fg("accent", "👤")} ${theme.fg("text", acct)}`,
          ].join(theme.fg("muted", " | "));
          lines.push(truncateToWidth(compactLine, width, theme.fg("muted", "…")));
          const contextAndQuota = showCodexQuota
            ? `${boldLabel(theme, "ctx:")}${ctxPct} ${quotaText}`
            : showIbmCredits
              ? `${boldLabel(theme, "ctx:")}${ctxPct} ${formatIbmCredits(theme)}`
              : `${boldLabel(theme, "ctx:")}${ctxPct}`;
          lines.push(truncateToWidth(contextAndQuota, width, theme.fg("muted", "…")));
        }

        lines.push(truncateToWidth(statusLine, width, theme.fg("muted", "…")));

        const extensionStatuses = footerData.getExtensionStatuses();
        if (extensionStatuses.size > 0) {
          const statusText = Array.from(extensionStatuses.entries())
            .sort(([a]: [string, string], [b]: [string, string]) => a.localeCompare(b))
            .map(([, text]: [string, string]) => text.replace(/[\r\n\t]/g, " ").replace(/ +/g, " ").trim())
            .join(" ");
          lines.push(truncateToWidth(theme.fg("text", statusText), width, theme.fg("muted", "…")));
        }

        return lines;
      },
    };
  });
}

function shouldRenderStatusLine(ctx: any): boolean {
  return ctx.mode === "tui" || ctx.mode === "rpc";
}

export default function enhancedStatusLine(pi: ExtensionAPI) {
  pi.registerCommand("status-refresh", {
    description: "Refresh quota or credit data for the active provider",
    handler: async (_args, ctx) => {
      try {
        const isIbm = ctx.model?.provider === "ibm-services-essentials";
        const refreshed = isIbm ? await queryIbmCredits() : await queryCodexQuota(ctx);
        const label = isIbm ? "IBM credit" : "Codex quota";
        ctx.ui.notify(refreshed ? `${label} status refreshed` : `${label} data was unavailable`, refreshed ? "info" : "warning");
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        ctx.ui.notify(`Status refresh failed: ${message}`, "error");
      }
    },
  });

  pi.on("session_start", (_event, ctx) => {
    if (!shouldRenderStatusLine(ctx)) return;
    installFooter(ctx);
    if (ctx.model?.provider === "ibm-services-essentials" && Date.now() - lastIbmBudgetRefreshAt > 5 * 60_000) {
      void queryIbmCredits().catch(() => false);
    }
  });

  pi.on("model_select", (event) => {
    if (event.model.provider === "ibm-services-essentials" && Date.now() - lastIbmBudgetRefreshAt > 5 * 60_000) {
      void queryIbmCredits().catch(() => false);
    }
    requestFooterRender?.();
  });

  pi.on("after_provider_response", (event, ctx) => {
    if (event.status < 200 || event.status >= 300) return;
    if (ctx.model?.provider === "openai-codex") captureOpenAICodexQuota(event.headers ?? {});
    if (ctx.model?.provider === "ibm-services-essentials") captureIbmCredits(event.headers ?? {});
  });
}
